if ( ! defined( 'ABSPATH' ) ) {
	exit; // Silence is golden.
}

/**
 * Single-file plugin: event forwarding + customer support chat.
 *
 * Every forwarder in this class follows the same contract, so no handler can
 * be left half-finished again:
 *  1. bail out early when the matching event toggle is off,
 *  2. extract a complete, human readable payload from the source object,
 *  3. hand that payload to self::send_to_messengers().
 *
 * Missing data is omitted from the message, never faked with a placeholder.
 */
class WP_Messenger_Forward {

	/**
	 * Plugin options name.
	 */
	const OPTION_NAME = 'wp_messenger_forward_settings';

	/**
	 * Stored schema version, used to run dbDelta when the tables change.
	 */
	const DB_VERSION_OPTION = 'wp_messenger_forward_db_version';

	/**
	 * Schema version marker; bump together with table changes.
	 */
	const SCHEMA_VERSION = '2.1.0';

	/**
	 * Long-poll cursors for the bots that support getUpdates().
	 */
	const TG_OFFSET_OPTION   = 'wp_messenger_forward_tg_offset';
	const BALE_OFFSET_OPTION = 'wp_messenger_forward_bale_offset';

	/**
	 * Cron hook used to pull operator replies back from the messengers.
	 */
	const RELAY_CRON_HOOK = 'wp_messenger_forward_relay';

	/**
	 * Chat tables (prefixed with $wpdb->prefix at runtime).
	 */
	const TABLE_CONVERSATIONS = 'wp_messenger_forward_conversations';
	const TABLE_MESSAGES      = 'wp_messenger_forward_messages';

	const NONCE_CHAT  = 'wp_messenger_chat';
	const NONCE_ADMIN = 'wp_messenger_admin';

	const LAST_ERROR_OPTION   = 'wp_messenger_forward_last_error';
	const MAX_TELEGRAM_LENGTH = 4096;
	const TICKET_LENGTH       = 6;

	/**
	 * Runtime cache of the merged settings array.
	 *
	 * @var array|null
	 */
	private static $settings_cache = null;

	/**
	 * Whether the chat widget markup was already printed this request.
	 *
	 * @var bool
	 */
	private static $chat_rendered = false;

	/**
	 * Per-request memo of the SHOW TABLES probe, so widget polling never has to
	 * ask the information schema every few seconds.
	 *
	 * @var bool|null
	 */
	private static $tables_exist = null;

	/* ---------------------------------------------------------------------
	 * Configuration
	 * ------------------------------------------------------------------ */

	/**
	 * Toggleable events with their labels and defaults.
	 *
	 * Single source of truth: the settings screen, the option sanitiser and
	 * the hook registration all read from here, so an event can never be
	 * declared in one place and forgotten in another.
	 *
	 * @return array<string,array{label:string,default:bool}>
	 */
	public static function event_definitions() {
		return array(
			'forward_comment'       => array( 'label' => 'New comments (pending ones included)', 'default' => true ),
			'forward_post_publish'  => array( 'label' => 'Posts and pages published', 'default' => true ),
			'forward_post_status'   => array( 'label' => 'Post status changes (pending review, trash, unpublish)', 'default' => false ),
			'forward_user_create'   => array( 'label' => 'New user registrations', 'default' => true ),
			'forward_order_created' => array( 'label' => 'WooCommerce orders created', 'default' => false ),
			'forward_order_status'  => array( 'label' => 'WooCommerce order status changes', 'default' => false ),
			'forward_product_view'  => array( 'label' => 'WooCommerce product views', 'default' => false ),
			'forward_page_view'     => array( 'label' => 'Page / post views', 'default' => false ),
			'forward_chat_message'  => array( 'label' => 'Support chat messages from customers', 'default' => true ),
		);
	}

	/**
	 * Default settings, including messenger credentials and event toggles.
	 *
	 * @return array
	 */
	public static function defaults() {
		$events = array();
		foreach ( self::event_definitions() as $key => $conf ) {
			$events[ $key ] = $conf['default'];
		}

		return array(
			'telegram_bot_token'       => '',
			'telegram_chat_id'         => '',
			'bale_bot_token'           => '',
			'bale_chat_id'             => '',
			'rocketchat_url'           => '',
			'rocketchat_user'          => '',
			'rocketchat_token'         => '',
			'rocketchat_room'          => '',
			'disable_web_page_preview' => true,
			'excerpt_length'           => 400,
			'http_timeout'             => 15,
			'log_errors'               => true,
			'status_post_types'        => array( 'post' ),
			'view_post_types'          => array( 'post' ),
			'view_dedupe_seconds'      => 1800,
			'exclude_admin_views'      => true,
			'chat_enabled'             => true,
			'chat_title'               => 'Support Chat',
			'chat_intro'               => 'Send us a message and we will reply here.',
			'chat_ask_contact'         => true,
			'chat_poll_seconds'        => 7,
			'chat_rate_limit'          => 8,
			'chat_rate_window'         => 60,
			'relay_enabled'            => false,
			'relay_schedule'           => 'wpmf_fast',
			'ingest_secret'            => '',
			'events'                   => $events,
		);
	}

	/**
	 * Read the settings merged over the defaults.
	 *
	 * Merging happens in memory instead of being written back to the options
	 * table, so serving a page never triggers an UPDATE on every hit.
	 *
	 * @return array
	 */
	public static function get_settings() {
		if ( null === self::$settings_cache ) {
			$stored   = get_option( self::OPTION_NAME, array() );
			$stored   = is_array( $stored ) ? $stored : array();
			$settings = array();

			foreach ( self::defaults() as $key => $default ) {
				$settings[ $key ] = array_key_exists( $key, $stored )
					? self::sanitize_value( $key, $stored[ $key ], $default )
					: $default;
			}

			self::$settings_cache = $settings;
		}

		return self::$settings_cache;
	}

	/**
	 * Single setting accessor.
	 *
	 * @param string $key      Setting key.
	 * @param mixed  $fallback Returned when the key is unknown.
	 * @return mixed
	 */
	public static function get( $key, $fallback = null ) {
		$settings = self::get_settings();

		return array_key_exists( $key, $settings ) ? $settings[ $key ] : $fallback;
	}

	/**
	 * Coerce a stored value to the type implied by its default.
	 *
	 * @param string $key     Setting key.
	 * @param mixed  $value   Raw stored value.
	 * @param mixed  $default Default value, used to infer the type.
	 * @return mixed
	 */
	private static function sanitize_value( $key, $value, $default ) {
		if ( 'events' === $key ) {
			$events = array();
			foreach ( self::event_definitions() as $event => $conf ) {
				$events[ $event ] = ( is_array( $value ) && array_key_exists( $event, $value ) )
					? (bool) $value[ $event ]
					: $conf['default'];
			}

			return $events;
		}

		if ( is_bool( $default ) ) {
			return (bool) $value;
		}

		if ( is_int( $default ) ) {
			return is_numeric( $value ) ? (int) $value : (int) $default;
		}

		if ( is_array( $default ) ) {
			if ( ! is_array( $value ) ) {
				$value = is_string( $value ) ? explode( ',', $value ) : array();
			}

			$clean = array();

			foreach ( $value as $item ) {
				if ( ! is_scalar( $item ) ) {
					continue;
				}
				$item = sanitize_key( trim( (string) $item ) );

				if ( '' !== $item ) {
					$clean[] = $item;
				}
			}

			return $clean;
		}

		if ( 'rocketchat_url' === $key ) {
			return is_scalar( $value ) ? esc_url_raw( (string) $value ) : '';
		}

		return is_scalar( $value ) ? sanitize_text_field( (string) $value ) : '';
	}

	/**
	 * Normalise a whole option row against the defaults.
	 *
	 * @param array $stored Stored options.
	 * @return array
	 */
	private static function normalize_options( $stored ) {
		$clean = array();

		foreach ( self::defaults() as $key => $default ) {
			$raw             = ( is_array( $stored ) && array_key_exists( $key, $stored ) ) ? $stored[ $key ] : $default;
			$clean[ $key ] = self::sanitize_value( $key, $raw, $default );
		}

		return $clean;
	}

	/**
	 * Does the stored row already contain every key?
	 *
	 * @param array $stored Stored options.
	 * @return bool
	 */
	private static function options_are_complete( $stored ) {
		if ( ! is_array( $stored ) ) {
			return false;
		}

		foreach ( array_keys( self::defaults() ) as $key ) {
			if ( ! array_key_exists( $key, $stored ) ) {
				return false;
			}
		}

		foreach ( array_keys( self::event_definitions() ) as $event ) {
			if ( ! array_key_exists( $event, (array) $stored['events'] ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Is an event forwarder enabled?
	 *
	 * @param string $event Event key as declared in self::event_definitions().
	 * @return bool
	 */
	public static function event_enabled( $event ) {
		$events = self::get( 'events', array() );

		return ! empty( $events[ $event ] );
	}

	/**
	 * Is at least one messenger fully configured?
	 *
	 * @return bool
	 */
	public static function has_transport() {
		$settings = self::get_settings();

		$telegram = '' !== $settings['telegram_bot_token'] && '' !== $settings['telegram_chat_id'];
		$bale     = '' !== $settings['bale_bot_token'] && '' !== $settings['bale_chat_id'];
		$rocket   = '' !== $settings['rocketchat_url'] && '' !== $settings['rocketchat_token'];

		return $telegram || $bale || $rocket;
	}

	/**
	 * Ensure defaults on every load.
	 *
	 * Kept for backwards compatibility with 2.0 installs. It now only fills
	 * genuinely missing keys and never rewrites the option on the frontend.
	 */
	public static function ensure_defaults() {
		$stored = get_option( self::OPTION_NAME, array() );

		if ( self::options_are_complete( $stored ) ) {
			return;
		}

		update_option( self::OPTION_NAME, self::normalize_options( $stored ) );
		self::$settings_cache = null;
	}

	/* ---------------------------------------------------------------------
	 * Activation / deactivation / database
	 * ------------------------------------------------------------------ */

	/**
	 * Plugin activation: seed options, create tables, schedule the relay.
	 */
	public static function on_activate() {
		$stored = get_option( self::OPTION_NAME, array() );

		if ( ! self::options_are_complete( $stored ) ) {
			update_option( self::OPTION_NAME, self::normalize_options( $stored ) );
		}

		self::install_database();
		self::schedule_relay();
	}

	/**
	 * Plugin deactivation: drop the cron hook so it does not linger.
	 */
	public static function on_deactivate() {
		wp_clear_scheduled_hook( self::RELAY_CRON_HOOK );
	}

	/**
	 * Chat table names.
	 *
	 * @param string $which "conversations" or "messages".
	 * @return string Fully qualified table name.
	 */
	public static function table( $which ) {
		global $wpdb;

		$name = 'messages' === $which ? self::TABLE_MESSAGES : self::TABLE_CONVERSATIONS;

		return $wpdb->prefix . $name;
	}

	/**
	 * Create/upgrade the chat tables.
	 */
	public static function install_database() {
		require_once ABSPATH . 'wp-admin/includes/upgrade.php';

		global $wpdb;

		$charset       = $wpdb->get_charset_collate();
		$conversations = self::table( 'conversations' );
		$messages      = self::table( 'messages' );

		dbDelta(
			"CREATE TABLE $conversations (
				id BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
				ticket VARCHAR(16) NOT NULL DEFAULT '',
				visitor_key CHAR(64) NOT NULL DEFAULT '',
				customer_name VARCHAR(190) NOT NULL DEFAULT '',
				customer_email VARCHAR(190) NOT NULL DEFAULT '',
				status VARCHAR(12) NOT NULL DEFAULT 'open',
				last_message_id BIGINT(20) UNSIGNED NOT NULL DEFAULT 0,
				customer_cursor BIGINT(20) UNSIGNED NOT NULL DEFAULT 0,
				unread_agents INT(11) NOT NULL DEFAULT 0,
				origin_chat_id VARCHAR(40) NOT NULL DEFAULT '',
				created_at DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00',
				updated_at DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00',
				PRIMARY KEY  (id),
				KEY ticket (ticket),
				KEY visitor_key (visitor_key,status,updated_at),
				KEY status (status,updated_at)
			) $charset;"
		);

		dbDelta(
			"CREATE TABLE $messages (
				id BIGINT(20) UNSIGNED NOT NULL AUTO_INCREMENT,
				conversation_id BIGINT(20) UNSIGNED NOT NULL DEFAULT 0,
				sender VARCHAR(12) NOT NULL DEFAULT 'customer',
				author_name VARCHAR(190) NOT NULL DEFAULT '',
				message TEXT NOT NULL,
				forwarded TINYINT(1) NOT NULL DEFAULT 0,
				created_at DATETIME NOT NULL DEFAULT '1970-01-01 00:00:00',
				PRIMARY KEY  (id),
				KEY conversation (conversation_id,id)
			) $charset;"
		);

		self::$tables_exist = null;
		update_option( self::DB_VERSION_OPTION, self::SCHEMA_VERSION );
	}

	/**
	 * Run dbDelta only when the schema version moved, and only in admin.
	 */
	public static function maybe_upgrade_database() {
		if ( ! is_admin() ) {
			return;
		}

		if ( (string) get_option( self::DB_VERSION_OPTION, '' ) !== self::SCHEMA_VERSION ) {
			self::install_database();
		}
	}

	/* ---------------------------------------------------------------------
	 * Hook wiring
	 * ------------------------------------------------------------------ */

	/**
	 * Register admin pages, frontend assets and every enabled forwarder.
	 */
	public static function init() {
		load_plugin_textdomain(
			'wp-messenger-forward',
			false,
			dirname( plugin_basename( __FILE__ ) ) . '/languages'
		);

		register_activation_hook( __FILE__, array( __CLASS__, 'on_activate' ) );
		register_deactivation_hook( __FILE__, array( __CLASS__, 'on_deactivate' ) );

		self::maybe_upgrade_database();

		add_action( 'admin_menu', array( __CLASS__, 'add_admin_menu' ) );
		add_action( 'admin_post_wpmf_save_settings', array( __CLASS__, 'handle_settings_save' ) );
		add_action( 'admin_post_wpmf_chat_action', array( __CLASS__, 'handle_chat_admin_action' ) );
		add_action( 'rest_api_init', array( __CLASS__, 'register_ingest_route' ) );
		add_filter( 'plugin_action_links_' . plugin_basename( __FILE__ ), array( __CLASS__, 'plugin_action_links' ) );
		add_filter( 'cron_schedules', array( __CLASS__, 'register_cron_schedules' ) );
		add_action( self::RELAY_CRON_HOOK, array( __CLASS__, 'relay_incoming_replies' ) );

		// Support chat endpoints. Customers are usually logged out, so both the
		// privileged and the nopriv action have to exist, and the action name
		// must be exactly what the widget posts (action: 'wpmf_send_message').
		foreach ( array(
			'wpmf_send_message'  => 'ajax_send_message',
			'wpmf_poll_messages' => 'ajax_poll_messages',
		) as $action => $handler ) {
			add_action( 'wp_ajax_' . $action, array( __CLASS__, $handler ) );
			add_action( 'wp_ajax_nopriv_' . $action, array( __CLASS__, $handler ) );
		}

		// The chat works without any configured messenger: forwarding is
		// simply skipped then, so register_forwarders() must not gate it.
		add_shortcode( 'customer_chat', array( __CLASS__, 'customer_chat_shortcode' ) );

		self::register_forwarders();
		self::schedule_relay();
	}

	/**
	 * Wire only the forwarders the user actually switched on.
	 */
	private static function register_forwarders() {
		if ( ! self::has_transport() ) {
			return;
		}

		if ( self::event_enabled( 'forward_comment' ) ) {
			add_action( 'comment_post', array( __CLASS__, 'forward_comment' ), 10, 2 );
		}

		if ( self::event_enabled( 'forward_post_publish' ) ) {
			add_action( 'publish_post', array( __CLASS__, 'forward_post_publish' ), 10, 2 );
			add_action( 'publish_page', array( __CLASS__, 'forward_post_publish' ), 10, 2 );
		}

		if ( self::event_enabled( 'forward_post_status' ) ) {
			add_action( 'transition_post_status', array( __CLASS__, 'forward_post_status_change' ), 10, 3 );
		}

		if ( self::event_enabled( 'forward_user_create' ) ) {
			add_action( 'register_post', array( __CLASS__, 'capture_registration_context' ), 10, 3 );
			add_action( 'user_register', array( __CLASS__, 'forward_user_create' ), 10, 1 );
		}

		if ( self::is_woocommerce_active() ) {
			if ( self::event_enabled( 'forward_order_created' ) ) {
				add_action( 'woocommerce_new_order', array( __CLASS__, 'forward_order_created' ), 10, 2 );
			}
			if ( self::event_enabled( 'forward_order_status' ) ) {
				add_action( 'woocommerce_order_status_changed', array( __CLASS__, 'forward_order_status_changed' ), 10, 3 );
			}
			if ( self::event_enabled( 'forward_product_view' ) ) {
				add_action( 'template_redirect', array( __CLASS__, 'forward_product_view' ) );
			}
		}

		if ( self::event_enabled( 'forward_page_view' ) ) {
			add_action( 'template_redirect', array( __CLASS__, 'forward_page_view' ) );
		}
	}

	/**
	 * WooCommerce available?
	 *
	 * @return bool
	 */
	public static function is_woocommerce_active() {
		return function_exists( 'WC' ) && class_exists( 'WooCommerce' );
	}

	/**
