	public static function add_admin_menu() {
		add_options_page(
			__( 'Messenger Forward Settings', 'wp-messenger-forward' ),
			__( 'Messenger Forward', 'wp-messenger-forward' ),
			'manage_options',
			'wp-messenger-forward',
