	/**
	 * Tell the operator the chat tables are missing after a partial activate.
	 */
	public static function maybe_delete_chat_table_notice() {
		if ( self::chat_tables_exist() ) {
			return;
		}

		add_action(
			'admin_notices',
			static function () {
				printf(
					'<div class="notice notice-warning"><p>%s</p></div>',
					esc_html__(
						'WP Messenger Forward: the support chat tables do not exist yet. Deactivate and reactivate the plugin to create them.',
						'wp-messenger-forward'
					)
				);
			}
		);
	}

	/**
	 * @return bool
	 */
	public static function chat_tables_exist() {
		global $wpdb;

		if ( null !== self::$tables_exist ) {
			return self::$tables_exist;
		}

		$conversations = self::table( 'conversations' );
		$messages      = self::table( 'messages' );

		self::$tables_exist = $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $conversations ) ) === $conversations
			&& $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $messages ) ) === $messages;

		return self::$tables_exist;
	}

	/* ---------------------------------------------------------------------
