	/**
	 * Turn arbitrary post content into a clean plain-text blob.
	 *
	 * The 2.0 code ran esc_html() over values before sending them to the
	 * messengers, which leaked HTML entities into the chat. Messengers get
	 * plain text, so shortcodes/embeds are stripped instead.
	 *
	 * @param string $html Raw content.
	 * @return string
	 */
	public static function to_plain_text( $html ) {
		$html = (string) $html;

		if ( '' === trim( $html ) ) {
			return '';
		}

		$html = wp_strip_all_tags( $html, true );
		$html = html_entity_decode( $html, ENT_QUOTES | ENT_HTML5, get_option( 'blog_charset', 'UTF-8' ) );
		$html = str_replace( array( "
", "
", "Â " ), array( "
", "
", ' ' ), $html );
		$html = preg_replace( '/[ 	]+/', ' ', (string) $html );
		$html = preg_replace( '/\n{3,}/', "

", (string) $html );
		// Shortcodes survive wp_strip_all_tags() because they are not tags.
		$html = preg_replace( '/\[[^\]\[]{1,255}\]/', '', (string) $html );

		return trim( (string) $html );
	}

	/**
	 * Truncate on a word boundary and add an ellipsis.
	 *
	 * @param string $text   Text.
	 * @param int    $length Max length.
	 * @return string
	 */
	public static function truncate( $text, $length = 400 ) {
		$text = (string) $text;
		$size = mb_strlen( $text, 'UTF-8' );

		if ( $size <= $length || $length < 2 ) {
			return $text;
		}

		$cut   = mb_substr( $text, 0, $length - 1, 'UTF-8' );
		$space = strrpos( $cut, ' ' );

		if ( false !== $space && $space > (int) ( $length / 2 ) ) {
			$cut = mb_substr( $cut, 0, $space, 'UTF-8' );
		}

		return rtrim( $cut, " \t\n\0\x0B.,;:-" ) . '…';
	}

	/**
	 * Configured excerpt length with a sane floor/ceiling.
	 *
	 * @return int
	 */
	private static function excerpt_length() {
		return (int) max( 80, min( 4000, (int) self::get( 'excerpt_length', 400 ) ) );
	}

	/**
	 * Build a message body from labelled rows, dropping empty rows.
	 *
	 * @param string $headline   First line (emoji + title).
	 * @param array  $fields     Label => value pairs; empty values are skipped.
	 * @param array  $paragraphs Free text blocks appended after the fields.
	 * @return string
	 */
	private static function build_message( $headline, array $fields = array(), array $paragraphs = array() ) {
		$lines = array( (string) $headline );

		foreach ( $fields as $label => $value ) {
			$value = trim( (string) $value );

			if ( '' === $value ) {
				continue;
			}

			$lines[] = is_int( $label ) ? $value : $label . ': ' . $value;
		}

		foreach ( $paragraphs as $block ) {
			$block = trim( (string) $block );

			if ( '' === $block ) {
				continue;
			}

			$lines[] = '';
			$lines[] = $block;
		}

		return implode( "\n", $lines );
	}

	/**
	 * Current UTC datetime for the DATETIME columns: every chat timestamp is stored in UTC.
	 *
	 * @return string
	 */
	private static function utc_now() {
		$now = new DateTimeImmutable( 'now', new DateTimeZone( 'UTC' ) );

		return $now->format( 'Y-m-d H:i:s' );
	}

	/**
	 * Localised date+time for a MySQL UTC datetime string.
	 *
	 * @param string $mysql_utc Datetime in UTC.
	 * @return string
	 */
	private static function format_datetime( $mysql_utc ) {
		if ( empty( $mysql_utc ) || '0000-00-00 00:00:00' === $mysql_utc ) {
			return '';
		}

		$timestamp = strtotime( $mysql_utc . ' UTC' );

		if ( false === $timestamp ) {
			return (string) $mysql_utc;
		}

		return date_i18n( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $timestamp );
	}

	/**
	 * Best-effort client IP, sanitised.
	 *
	 * @return string
	 */
	private static function client_ip() {
		if ( empty( $_SERVER['REMOTE_ADDR'] ) ) {
			return '';
		}

		$ip = sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) );

		return filter_var( $ip, FILTER_VALIDATE_IP ) ? $ip : '';
	}

	/**
	 * Log a transport error, guarded by the matching setting.
	 *
	 * @param string $message Message.
	 */
	private static function log( $message ) {
		if ( self::get( 'log_errors', true ) ) {
			error_log( '[WP Messenger Forward] ' . $message );
		}
	}

	/**
	 * Remember the last transport error so the settings screen can show it.
	 *
	 * @param string $transport Transport key.
	 * @param string $error     Error text.
	 */
	private static function record_error( $transport, $error ) {
		update_option(
			self::LAST_ERROR_OPTION,
			array(
				'transport' => $transport,
				'error'     => substr( (string) $error, 0, 400 ),
				'time'      => self::utc_now(),
			),
			false
		);
	}

	/* ---------------------------------------------------------------------
	 * Event forwarders: extraction
	 * ------------------------------------------------------------------ */

	/**
	 * Forward a newly posted comment.
	 *
	 * @param int        $comment_id Comment ID.
	 * @param int|string $approved   Approved flag: 0 (pending), 1, "spam", "trash".
	 */
	public static function forward_comment( $comment_id, $approved = 0 ) {
		if ( ! self::event_enabled( 'forward_comment' ) ) {
			return;
		}

		$comment = get_comment( (int) $comment_id );

		if ( ! $comment || ! $comment->comment_post_ID ) {
			return;
		}

		$post = get_post( (int) $comment->comment_post_ID );

		if ( ! $post ) {
			return;
		}

		$author = trim( (string) $comment->comment_author );

		if ( '' === $author ) {
			$author = __( 'Anonymous', 'wp-messenger-forward' );
		}

		if ( (int) $comment->user_id > 0 ) {
			$author .= ' #' . (int) $comment->user_id;
		}

		$type   = (string) get_comment_type( $comment );
		$parent = (int) $comment->comment_parent > 0 ? get_comment( (int) $comment->comment_parent ) : null;

		$fields = array(
			'Post'        => get_the_title( $post ),
			'URL'         => get_permalink( $post ),
			'Author'      => $author,
			'Email'       => (string) $comment->comment_author_email,
			'IP'          => (string) $comment->comment_author_IP,
			'Type'        => 'comment' === $type ? '' : $type,
			'Status'      => self::comment_status_label( $approved ),
			'Posted'      => self::format_datetime( $comment->comment_date_gmt ),
			'In reply to' => $parent ? trim( (string) $parent->comment_author ) : '',
			'Actions'     => admin_url( 'comment.php?action=editcomment&c=' . (int) $comment->comment_ID ),
		);

		if ( '1' !== (string) $approved && 'approved' !== (string) $approved ) {
			$fields['Moderate'] = admin_url( 'edit-comments.php?pmoderation=held&comment_post_ID=' . (int) $post->ID );
		}

		$message = self::build_message(
			'💬 ' . __( 'New comment', 'wp-messenger-forward' ),
			$fields,
			array( self::truncate( self::to_plain_text( $comment->comment_content ), self::excerpt_length() ) )
		);

		self::send_to_messengers( $message );
	}

	/**
	 * Human readable moderation state of a comment.
	 *
	 * @param int|string $approved Approved flag.
	 * @return string
	 */
	private static function comment_status_label( $approved ) {
		switch ( (string) $approved ) {
			case '1':
				return __( 'Approved', 'wp-messenger-forward' );
			case 'spam':
				return __( 'Marked as spam', 'wp-messenger-forward' );
			case 'trash':
				return __( 'Trashed', 'wp-messenger-forward' );
			default:
				return __( 'Awaiting moderation', 'wp-messenger-forward' );
		}
	}

	/**
	 * Forward a published post or page.
	 *
	 * @param int $post_id Post ID.
	 */
	public static function forward_post_publish( $post_id ) {
		if ( ! self::event_enabled( 'forward_post_publish' ) ) {
			return;
		}

		$post = get_post( (int) $post_id );

		if ( ! $post || 'auto-draft' === $post->post_status ) {
			return;
		}

		$message = self::build_message(
			'📢 ' . __( 'New post published', 'wp-messenger-forward' ),
			self::post_fields( $post ),
			array( self::post_summary( $post ) )
		);

		self::send_to_messengers( $message );
	}

	/**
	 * Common post facts shared by the publish and status forwarders.
	 *
	 * @param WP_Post $post   Post object.
	 * @param bool    $use_edit_link Use the admin edit link instead of the permalink.
	 * @return array
	 */
	private static function post_fields( WP_Post $post, $use_edit_link = false ) {
		$post_type = get_post_type_object( $post->post_type );

		$fields = array(
			'Title'      => get_the_title( $post ),
			'Type'       => $post_type ? (string) $post_type->labels->singular_name : $post->post_type,
			'Author'     => (string) get_the_author_meta( 'display_name', (int) $post->post_author ),
			'URL'        => $use_edit_link ? '' : get_permalink( $post ),
			'Edit'       => $use_edit_link ? get_edit_post_link( $post->ID, 'raw' ) : '',
			'Categories' => self::term_names( $post->ID, 'category' ),
			'Tags'       => self::term_names( $post->ID, 'post_tag' ),
			'Words'      => (string) str_word_count( wp_strip_all_tags( $post->post_content ) ),
			'Date'       => self::format_datetime( 'publish' === $post->post_status ? $post->post_date_gmt : $post->post_modified_gmt ),
		);

		return $fields;
	}

	/**
	 * Comma separated term names, never a WP_Error.
	 *
	 * @param int    $post_id  Post ID.
	 * @param string $taxonomy Taxonomy name.
	 * @return string
	 */
	private static function term_names( $post_id, $taxonomy ) {
		if ( ! taxonomy_exists( $taxonomy ) ) {
			return '';
		}

		$terms = wp_get_post_terms( (int) $post_id, $taxonomy, array( 'fields' => 'names' ) );

		return is_wp_error( $terms ) ? '' : implode( ', ', (array) $terms );
	}

	/**
	 * Excerpt when there is one, otherwise the opening of the content.
	 *
	 * @param WP_Post $post Post object.
	 * @return string
	 */
	private static function post_summary( WP_Post $post ) {
		$excerpt = self::to_plain_text( $post->post_excerpt );

		if ( '' !== $excerpt ) {
			return self::truncate( $excerpt, self::excerpt_length() );
		}

		$content = self::to_plain_text( $post->post_content );

		if ( '' === $content ) {
			return '';
		}

		// Respect the more tag when present.
		$parts = explode( '<!--more-->', $post->post_content, 2 );

		if ( count( $parts ) > 1 ) {
			$content = self::to_plain_text( $parts[0] );
		}

		return self::truncate( $content, self::excerpt_length() );
	}

	/**
	 * Forward meaningful post status transitions.
	 *
	 * This method used to be referenced by a hook that no one had written;
	 * it now reports the transitions a moderator actually cares about.
	 *
	 * @param string  $new_status New status.
	 * @param string  $old_status Old status.
	 * @param WP_Post $post       Post object.
	 */
	public static function forward_post_status_change( $new_status, $old_status, $post ) {
		if ( ! self::event_enabled( 'forward_post_status' ) ) {
			return;
		}

		if ( ! $post instanceof WP_Post || $new_status === $old_status ) {
			return;
		}

		$monitored = (array) self::get( 'status_post_types', array( 'post' ) );

		if ( ! in_array( $post->post_type, $monitored, true ) ) {
			return;
		}

		$interesting = array( 'pending', 'publish', 'trash', 'draft', 'private', 'future' );

		if ( ! in_array( $new_status, $interesting, true ) || ! in_array( $old_status, $interesting, true ) ) {
			return;
		}

		// Draft -> auto-draft churn and "publish -> publish" saves are noise.
		if ( 'publish' === $new_status && 'draft' === $old_status && (string) $post->post_date_gmt === (string) $post->post_modified_gmt ) {
			return;
		}

		$headline = '🗂️ ';

		switch ( $new_status ) {
			case 'pending':
				$headline .= __( 'Post awaiting review', 'wp-messenger-forward' );
				break;
			case 'publish':
				$headline .= 'draft' === $old_status || 'pending' === $old_status
					? __( 'Post published', 'wp-messenger-forward' )
					: __( 'Post re-published', 'wp-messenger-forward' );
				break;
			case 'trash':
				$headline .= __( 'Post moved to trash', 'wp-messenger-forward' );
				break;
			case 'draft':
				$headline .= __( 'Post unpublished', 'wp-messenger-forward' );
				break;
			default:
				$headline .= __( 'Post status changed', 'wp-messenger-forward' );
		}

		$fields         = self::post_fields( $post, 'publish' !== $new_status );
		$fields         = array_merge(
			array(
				'From' => $old_status,
				'To'   => $new_status,
			),
			$fields
		);
		$fields['Time'] = self::format_datetime( $post->post_modified_gmt );

		if ( 'pending' === $new_status ) {
			$fields['Review'] = admin_url( 'edit.php?post_status=pending&post_type=' . $post->post_type );
		}

		self::send_to_messengers( self::build_message( $headline, $fields ) );
	}

	/**
	 * Remember the requester's IP/user agent while validation runs, so the
	 * registration notification can report it after the user exists.
	 *
	 * @param string   $user_login Sanitised user login.
	 * @param string   $user_email Sanitised user email.
	 * @param WP_Error $errors     Validation errors.
	 */
	public static function capture_registration_context( $user_login, $user_email, $errors ) {
		if ( $errors instanceof WP_Error && $errors->has_errors() ) {
			return;
		}

		$key = 'wpmf_reg_' . hash( 'sha256', strtolower( (string) $user_email ) );

		set_transient(
			$key,
			array(
				'ip'    => self::client_ip(),
				'login' => (string) $user_login,
			),
			5 * MINUTE_IN_SECONDS
		);
	}

	/**
	 * Forward a new user registration.
	 *
	 * @param int $user_id New user ID.
	 */
	public static function forward_user_create( $user_id ) {
		if ( ! self::event_enabled( 'forward_user_create' ) ) {
			return;
		}

		$user = get_userdata( (int) $user_id );

		if ( ! $user ) {
			return;
		}

		$roles = array_map(
			static function ( $role ) {
				// translate_user_role() is not guaranteed outside wp-admin.
				return function_exists( 'translate_user_role' )
					? translate_user_role( (string) $role )
					: (string) $role;
			},
			(array) $user->roles
		);

		$registered = $user->user_registered ? $user->user_registered : '';
		$ip         = '';
		$key        = 'wpmf_reg_' . hash( 'sha256', strtolower( (string) $user->user_email ) );
		$context    = get_transient( $key );

		if ( is_array( $context ) ) {
			$ip = isset( $context['ip'] ) ? (string) $context['ip'] : '';
			delete_transient( $key );
		}

		$message = self::build_message(
			'👤 ' . __( 'New user registered', 'wp-messenger-forward' ),
			array(
				'Username' => $user->user_login,
				'Name'     => trim( $user->first_name . ' ' . $user->last_name ) ?: $user->display_name,
				'Email'    => $user->user_email,
				'Roles'    => implode( ', ', $roles ),
				'Register' => self::format_datetime( str_replace( ' ', ' ', $registered ) ),
				'IP'       => $ip,
				'Profile'  => admin_url( 'user-edit.php?user_id=' . (int) $user->ID ),
			)
		);

		self::send_to_messengers( $message );
	}

	/**
	 * Forward a new WooCommerce order.
	 *
	 * @param int      $order_id Order ID.
	 * @param WC_Order|null $theorder Order instance passed by WooCommerce.
	 */
	public static function forward_order_created( $order_id, $theorder = null ) {
		if ( ! self::event_enabled( 'forward_order_created' ) || ! self::is_woocommerce_active() ) {
			return;
		}

		if ( $theorder instanceof WC_Order ) {
			$order = $theorder;
		} else {
			$order = wc_get_order( (int) $order_id );
		}

		if ( ! $order instanceof WC_Order ) {
			return;
		}

		// Orders drafted in the admin are not real sales yet.
		if ( in_array( $order->get_status(), array( 'auto-draft', 'draft' ), true ) ) {
			return;
		}

		self::send_to_messengers( self::build_order_message( $order ) );
	}

	/**
	 * The full order snapshot: header, customer, items and totals.
	 *
	 * @param WC_Order $order Order.
	 * @return string
	 */
	private static function build_order_message( WC_Order $order ) {
		$customer_name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );
		$customer      = '' !== $customer_name ? $customer_name : __( 'Guest', 'wp-messenger-forward' );

		if ( $order->get_customer_id() ) {
			$customer .= ' (#' . $order->get_customer_id() . ')';
		}

		$fields = array(
			'Order'    => '#' . $order->get_order_number() . ' (ID ' . $order->get_id() . ')',
			'Status'   => wc_get_order_status_name( $order->get_status() ),
			'Placed'   => self::format_datetime( $order->get_date_created() ? $order->get_date_created()->format( 'Y-m-d H:i:s' ) : '' ),
			'Customer' => $customer,
			'Email'    => (string) $order->get_billing_email(),
			'Phone'    => (string) $order->get_billing_phone(),
			'Billing'  => self::to_plain_text( $order->get_formatted_billing_address() ),
			'Shipping' => $order->needs_shipping_address() ? self::to_plain_text( $order->get_formatted_shipping_address() ) : '',
			'Payment'  => (string) $order->get_payment_method_title(),
			'Total'    => wp_strip_all_tags( $order->get_formatted_order_total() ),
			'View'     => $order->get_view_order_url(),
			'Admin'    => $order->get_edit_order_url(),
		);

		$paragraphs = array(
			self::render_order_items( $order ),
			self::render_order_totals( $order ),
		);

		$note = trim( (string) $order->get_customer_note() );

		if ( '' !== $note ) {
			$paragraphs[] = '💭 ' . __( 'Customer note', 'wp-messenger-forward' ) . ":\n" . self::truncate( self::to_plain_text( $note ), 300 );
		}

		return self::build_message(
			'🛒 ' . sprintf(
				/* translators: %s: order number. */
				__( 'New order %s', 'wp-messenger-forward' ),
				'#' . $order->get_order_number()
			),
			$fields,
			$paragraphs
		);
	}

	/**
	 * Line items of an order, one per row.
	 *
	 * @param WC_Order $order Order.
	 * @return string
	 */
	private static function render_order_items( WC_Order $order ) {
		$lines = array();

		foreach ( $order->get_items() as $item ) {
			if ( ! is_object( $item ) || ! is_callable( array( $item, 'get_name' ) ) ) {
				continue;
			}

			$name  = $item->get_name();
			$qty   = (float) $item->get_quantity();
			$sku   = '';
			$meta  = '';

			if ( is_callable( array( $item, 'get_sku' ) ) ) {
				$sku = (string) $item->get_sku();
			}

			if ( is_callable( array( $item, 'get_formatted_variation_attributes' ) ) ) {
				$variation = $item->get_formatted_variation_attributes( true );
				$meta      = self::to_plain_text( $variation );
			}

			$row = sprintf(
				'• %s × %s%s',
				$name,
				rtrim( rtrim( number_format_i18n( $qty, 2 ), '0' ), '.' ),
				'' !== $sku ? ' [' . $sku . ']' : ''
			);

			if ( '' !== $meta ) {
				$row .= ' — ' . $meta;
			}

			$subtotal = wp_strip_all_tags( $order->get_formatted_line_subtotal( $item ) );

			if ( '' !== $subtotal ) {
				$row .= ' = ' . $subtotal;
			}

			$lines[] = $row;
		}

		foreach ( $order->get_fee_items() as $fee ) {
			$lines[] = sprintf( '• %s × %s = %s', $fee->get_name(), number_format_i18n( (float) $fee->get_quantity() ), wp_strip_all_tags( $order->get_formatted_line_subtotal( $fee ) ) );
		}

		foreach ( $order->get_shipping_methods() as $shipping ) {
			$lines[] = sprintf( '• %s: %s', __( 'Shipping', 'wp-messenger-forward' ), $shipping->get_method_title() );
		}

		if ( empty( $lines ) ) {
			return '';
		}

		return "🧾 " . implode( "\n", $lines );
	}

	/**
	 * Totals block (subtotal, discount, shipping, tax, total).
	 *
	 * @param WC_Order $order Order.
	 * @return string
	 */
	private static function render_order_totals( WC_Order $order ) {
		$currency = get_woocommerce_currency_symbol( $order->get_currency() );
		$lines    = array();

		$add = static function ( $label, $value ) use ( &$lines, $currency ) {
			if ( (float) $value === 0.0 ) {
				return;
			}
			$lines[] = sprintf( '%s: %s%s', $label, $currency, number_format_i18n( (float) $value, wc_get_price_decimals() ) );
		};

		$add( __( 'Subtotal', 'wp-messenger-forward' ), $order->get_subtotal() );
		$add( __( 'Discount', 'wp-messenger-forward' ), -1 * abs( (float) $order->get_total_discount( false ) ) );
		$add( __( 'Shipping', 'wp-messenger-forward' ), $order->get_shipping_total() );
		$add( __( 'Taxes', 'wp-messenger-forward' ), $order->get_total_tax() );
		$add( __( 'Total', 'wp-messenger-forward' ), $order->get_total() );

		if ( empty( $lines ) ) {
			return '';
		}

		return implode( "\n", $lines );
	}

	/**
	 * Forward a WooCommerce order status change.
	 *
	 * @param int    $order_id   Order ID.
	 * @param string $old_status Previous status.
	 * @param string $new_status New status.
	 */
	public static function forward_order_status_changed( $order_id, $old_status, $new_status ) {
		if ( ! self::event_enabled( 'forward_order_status' ) || ! self::is_woocommerce_active() ) {
			return;
		}

		$order = wc_get_order( (int) $order_id );

		if ( ! $order instanceof WC_Order || $old_status === $new_status ) {
			return;
		}

		$customer_name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );

		$message = self::build_message(
			'🔄 ' . sprintf(
				/* translators: 1: order number, 2: status. */
				__( 'Order %1$s is now %2$s', 'wp-messenger-forward' ),
				'#' . $order->get_order_number(),
				(string) wc_get_order_status_name( $new_status )
			),
			array(
				'From'     => wc_get_order_status_name( $old_status ),
				'To'       => wc_get_order_status_name( $new_status ),
				'Customer' => '' !== $customer_name ? $customer_name : __( 'Guest', 'wp-messenger-forward' ),
				'Email'    => (string) $order->get_billing_email(),
				'Total'    => wp_strip_all_tags( $order->get_formatted_order_total() ),
				'Payment'  => (string) $order->get_payment_method_title(),
				'Items'    => (string) count( $order->get_items() ),
				'Admin'    => $order->get_edit_order_url(),
			)
		);

		self::send_to_messengers( $message );
	}

	/**
	 * Forward a single product view, deduplicated per visitor.
	 */
	public static function forward_product_view() {
		if ( ! self::event_enabled( 'forward_product_view' ) || ! function_exists( 'wc_get_product' ) ) {
			return;
		}

		if ( ! is_product() ) {
			return;
		}

		$product_id = (int) get_queried_object_id();
		$product    = $product_id > 0 ? wc_get_product( $product_id ) : null;

		if ( ! $product instanceof WC_Product ) {
			return;
		}

		if ( ! self::throttle( 'product_view|' . $product_id, (int) self::get( 'view_dedupe_seconds', 1800 ) ) ) {
			return;
		}

		$views = (int) get_post_meta( $product_id, '_wpmf_product_views', true ) + 1;
		update_post_meta( $product_id, '_wpmf_product_views', $views );

		self::send_to_messengers(
			self::build_message(
				'👁️ ' . __( 'Product viewed', 'wp-messenger-forward' ),
				array(
					'Product' => (string) $product->get_name(),
					'SKU'     => (string) $product->get_sku(),
					'Price'   => wp_strip_all_tags( wc_price( $product->get_price(), array( 'currency' => $product->get_currency() ) ) ),
					'Stock'   => $product->managing_stock() ? (string) $product->get_stock_quantity() : '',
					'Views'   => (string) $views,
					'URL'     => (string) get_permalink( $product_id ),
					'Visitor' => self::audience_key(),
				)
			)
		);
	}

	/**
	 * Forward a singular page view, deduplicated per visitor and page.
	 */
	public static function forward_page_view() {
		if ( ! self::event_enabled( 'forward_page_view' ) || ! is_singular() ) {
			return;
		}

		$post = get_queried_object();

		if ( ! $post instanceof WP_Post ) {
			return;
		}

		$allowed = (array) self::get( 'view_post_types', array( 'post' ) );

		if ( ! in_array( $post->post_type, $allowed, true ) ) {
			return;
		}

		// Product pages are singular too: let the product forwarder own them.
		if ( self::event_enabled( 'forward_product_view' ) && function_exists( 'is_product' ) && is_product() ) {
			return;
		}

		// Do not spam the channel with administrators previewing their own site.
		if ( self::get( 'exclude_admin_views', true ) && is_user_logged_in() && current_user_can( 'manage_options' ) ) {
			return;
		}

		if ( post_password_required( $post ) || ! self::throttle( 'page_view|' . $post->ID, (int) self::get( 'view_dedupe_seconds', 1800 ) ) ) {
			return;
		}

		$post_type = get_post_type_object( $post->post_type );

		self::send_to_messengers(
			self::build_message(
				'📄 ' . __( 'Page viewed', 'wp-messenger-forward' ),
				array(
					'Title'    => get_the_title( $post ),
					'Type'     => $post_type ? (string) $post_type->labels->singular_name : $post->post_type,
					'URL'      => get_permalink( $post ),
					'Referrer' => self::safe_url( wp_get_referer() ),
					'Author'   => (string) get_the_author_meta( 'display_name', (int) $post->post_author ),
					'Views'    => self::increment_view_count( $post->ID ),
					'Visitor'  => self::audience_key(),
				)
			)
		);
	}

	/**
	 * Per-post view counter, returned as a display string.
	 *
	 * @param int $post_id Post ID.
	 * @return string
	 */
	private static function increment_view_count( $post_id ) {
		$views = (int) get_post_meta( (int) $post_id, '_wpmf_views', true ) + 1;
		update_post_meta( (int) $post_id, '_wpmf_views', $views );

		return number_format_i18n( $views );
	}

	/**
	 * Only allow http(s) references into a chat message.
	 *
	 * @param string|false $url Candidate URL.
	 * @return string
	 */
	private static function safe_url( $url ) {
		$url = (string) $url;

		if ( '' === $url ) {
			return '';
		}

		return preg_match( '#^https?://#i', $url ) ? $url : '';
	}

	/**
	 * Stable identifier for the current visitor, used to deduplicate views.
	 *
	 * @return string
	 */
	private static function audience_key() {
		$ua = isset( $_SERVER['HTTP_USER_AGENT'] ) ? substr( sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ), 0, 200 ) : '';

		return substr( hash( 'sha256', self::client_ip() . '|' . $ua ), 0, 12 );
	}

	/**
	 * One-shot suppression window, used by the view forwarders so a browsing
	 * visitor cannot flood a channel. The chat uses check_rate_limit() instead,
	 * which counts messages per window.
	 *
	 * @param string $key Bucket key.
	 * @param int    $ttl Seconds during which repeat calls are suppressed.
	 * @return bool TRUE when this call is allowed through.
	 */
	private static function throttle( $key, $ttl ) {
		$bucket = 'wpmf_throttle_' . hash( 'sha256', $key );

		if ( get_transient( $bucket ) ) {
			return false;
		}

		set_transient( $bucket, 1, max( 5, (int) $ttl ) );

		return true;
	}

	/* ---------------------------------------------------------------------
	 * Transports
	 * ------------------------------------------------------------------ */

	/**
	 * Send a message to every configured messenger.
	 *
	 * @param string $message Plain text message.
	 * @return array<string,bool> Per-transport success flags.
	 */
	public static function send_to_messengers( $message ) {
		$message = self::normalize_outgoing( $message );

		if ( '' === $message ) {
			return array();
		}

		$settings = self::get_settings();
		$results  = array();

		if ( '' !== $settings['telegram_bot_token'] && '' !== $settings['telegram_chat_id'] ) {
			$results['telegram'] = self::bot_api_broadcast( 'telegram', $message );
		}

		if ( '' !== $settings['bale_bot_token'] && '' !== $settings['bale_chat_id'] ) {
			$results['bale'] = self::bot_api_broadcast( 'bale', $message );
		}

		if ( '' !== $settings['rocketchat_url'] && '' !== $settings['rocketchat_token'] ) {
			$results['rocketchat'] = self::rocketchat_send( $message );
		}

		/**
		 * Filters the per-transport send results.
		 *
		 * @param array  $results Transport => bool.
		 * @param string $message   Message that was sent.
		 */
		return apply_filters( 'wp_messenger_forward_sent', $results, $message );
	}

	/**
	 * Normalise a message for the wire: unix newlines, no control characters.
	 *
	 * @param string $message Raw message.
	 * @return string
	 */
	private static function normalize_outgoing( $message ) {
		$message = wp_strip_all_tags( (string) $message );
		$message = str_replace( array( "
", "
" ), "
", $message );
		// ASCII control bytes never occur inside a valid UTF-8 multi-byte sequence.
		$message = preg_replace( '/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/', '', $message );
		$message = preg_replace( '/\n{4,}/', "


", (string) $message );

		return trim( (string) $message );
	}

	/**
	 * HTTP timeout with bounds.
	 *
	 * @return int
	 */
	private static function http_timeout() {
		return (int) max( 3, min( 60, (int) self::get( 'http_timeout', 15 ) ) );
	}

	/**
	 * API base for the two Telegram-compatible bots.
	 *
	 * @param string $transport "telegram" or "bale".
	 * @return string
	 */
	private static function bot_api_base( $transport ) {
		return 'bale' === $transport ? 'https://api.bale.ai/bot' : 'https://api.telegram.org/bot';
	}

	/**
	 * @param string $transport "telegram" or "bale".
	 * @return string
	 */
	private static function bot_token( $transport ) {
		return (string) self::get( 'bale' === $transport ? 'bale_bot_token' : 'telegram_bot_token' );
	}

	/**
	 * @param string $transport "telegram" or "bale".
	 * @return string
	 */
	private static function bot_chat_id( $transport ) {
		return (string) self::get( 'bale' === $transport ? 'bale_chat_id' : 'telegram_chat_id' );
	}

	/**
	 * Send one message through the Telegram-compatible Bot API.
	 *
	 * Long payloads are split, flood control (HTTP 429) is honoured once and
	 * every failure ends up in the error log plus the settings screen.
	 *
	 * @param string $transport "telegram" or "bale".
	 * @param string $message   Plain text message.
	 * @return bool
	 */
	private static function bot_api_broadcast( $transport, $message ) {
		$token = (string) self::bot_token( $transport );

		if ( ! preg_match( '#^\d+:[A-Za-z0-9_\-]+$#', $token ) ) {
			self::fail( $transport, __( 'The bot token is malformed. Expected format: 123456789:ABCdef.', 'wp-messenger-forward' ) );

			return false;
		}

		$url = self::bot_api_base( $transport ) . $token . '/sendMessage';

		foreach ( self::split_message( $message, self::MAX_TELEGRAM_LENGTH ) as $chunk ) {
			$payload = array(
				'chat_id' => self::bot_chat_id( $transport ),
				'text'    => $chunk,
				// Plain text on purpose: the payload already contains user data
				// and enabling a parser would turn it into an injection vector.
				'disable_web_page_preview' => (bool) self::get( 'disable_web_page_preview', true ),
			);

			$response = self::http_post_json( $url, $payload, $transport );

			if ( ! empty( $response['ok'] ) ) {
				continue;
			}

			// Telegram/Bale answer 429 with a retry_after hint for groups.
			if ( 429 === $response['code'] && $response['retry_after'] > 0 && $response['retry_after'] <= 2 && ! wp_doing_cron() ) {
				usleep( (int) ( $response['retry_after'] * 1000000 ) );

				$response = self::http_post_json( $url, $payload, $transport );

				if ( ! empty( $response['ok'] ) ) {
					continue;
				}
			}

			self::fail( $transport, $response['error'] );

			return false;
		}

		return true;
	}

	/**
	 * Split a message into Bot-API sized chunks, line aware.
	 *
	 * @param string $message Message.
	 * @param int    $limit   Max characters per chunk.
	 * @return array<int,string>
	 */
	private static function split_message( $message, $limit ) {
		$limit = max( 200, (int) $limit );

		if ( mb_strlen( $message, 'UTF-8' ) <= $limit ) {
			return array( $message );
		}

		$chunks = array();
		$current = '';

		foreach ( explode( "\n", $message ) as $line ) {
			while ( mb_strlen( $line, 'UTF-8' ) > $limit ) {
				if ( '' !== $current ) {
					$chunks[]  = $current;
					$current   = '';
				}
				$chunks[] = mb_substr( $line, 0, $limit, 'UTF-8' );
				$line     = mb_substr( $line, $limit, mb_strlen( $line, 'UTF-8' ) - $limit, 'UTF-8' );
			}

			$candidate = '' === $current ? $line : $current . "\n" . $line;

			if ( mb_strlen( $candidate, 'UTF-8' ) > $limit ) {
				$chunks[] = $current;
				$current  = $line;
			} else {
				$current = $candidate;
			}
		}

		if ( '' !== $current ) {
			$chunks[] = $current;
		}

		return array_values( array_filter( $chunks, 'strlen' ) );
	}

	/**
	 * POST JSON and return a normalised result.
	 *
	 * @param string $url       Endpoint.
	 * @param array  $payload   Body.
	 * @param string $transport Label used in error messages.
	 * @return array{ok:bool,code:int,body:array,error:string,retry_after:int}
	 */
	private static function http_post_json( $url, array $payload, $transport ) {
		$result = array(
			'ok'          => false,
			'code'        => 0,
			'body'        => array(),
			'error'       => '',
			'retry_after' => 0,
		);

		$response = wp_remote_post(
			$url,
			array(
				'timeout'     => self::http_timeout(),
				'redirection' => 2,
				'headers'     => array( 'Content-Type' => 'application/json; charset=utf-8' ),
				'body'        => wp_json_encode( $payload ),
			)
		);

		if ( is_wp_error( $response ) ) {
			$result['error'] = $response->get_error_message();

			return $result;
		}

		$code = (int) wp_remote_retrieve_response_code( $response );
		$body = json_decode( (string) wp_remote_retrieve_body( $response ), true );
		$body = is_array( $body ) ? $body : array();

		$result['code'] = $code;
		$result['body'] = $body;
		$result['ok']   = $code >= 200 && $code < 300 && ( ! isset( $body['ok'] ) || true === (bool) $body['ok'] );

		if ( ! $result['ok'] ) {
			$message = isset( $body['description'] ) ? (string) $body['description'] : '';

			if ( '' === $message ) {
				$message = isset( $body['error'] ) ? (string) $body['error'] : '';
			}

			$result['error'] = sprintf(
				/* translators: 1: HTTP status code, 2: upstream message. */
				__( 'HTTP %1$s — %2$s', 'wp-messenger-forward' ),
				$code,
				'' !== $message ? $message : wp_remote_retrieve_response_message( $response )
			);

			if ( isset( $body['parameters']['retry_after'] ) ) {
				$result['retry_after'] = (int) $body['parameters']['retry_after'];
			}
		}

		return $result;
	}

	/**
	 * Record and log a transport failure.
	 *
	 * @param string $transport Transport key.
	 * @param string $error     Error text.
	 */
	private static function fail( $transport, $error ) {
		self::record_error( $transport, $error );
		self::log( $transport . ': ' . $error );
	}

	/**
	 * Send a message to Rocket.Chat through chat.postMessage.
	 *
	 * @param string $message Plain text message.
	 * @return bool
	 */
	private static function rocketchat_send( $message ) {
		$base = trim( (string) self::get( 'rocketchat_url' ) );
		$room = trim( (string) self::get( 'rocketchat_room' ) );
		$token = (string) self::get( 'rocketchat_token' );
		$user  = (string) self::get( 'rocketchat_user' );

		if ( '' === $base ) {
			self::fail( 'rocketchat', __( 'The Rocket.Chat API URL is empty.', 'wp-messenger-forward' ) );

			return false;
		}

		if ( '' === $room ) {
			self::fail( 'rocketchat', __( 'No Rocket.Chat channel or room ID is configured.', 'wp-messenger-forward' ) );

			return false;
		}

		if ( ! preg_match( '#/api/v1$#', $base ) ) {
			$base = rtrim( $base, '/' ) . '/api/v1';
		}

		$payload = array( 'text' => $message );

		// A bare alphanumeric id is a roomId; anything else is a channel name.
		if ( preg_match( '#^[0-9a-zA-Z]{12,32}$#', $room ) ) {
			$payload['roomId'] = $room;
		} else {
			$payload['channel'] = 0 === strpos( $room, '@' ) ? $room : '#' . ltrim( $room, '#' );
		}

		$headers = array( 'Content-Type' => 'application/json; charset=utf-8' );

		if ( '' !== $user ) {
			// Session token auth: needs both the user id and its auth token.
			$headers['X-User-Id']   = $user;
			$headers['X-Auth-Token'] = $token;
		} elseif ( false !== strpos( $token, '.' ) ) {
			// Personal access tokens are used as a Bearer credential instead.
			$headers['Authorization'] = 'Bearer ' . $token;
		} else {
			self::fail( 'rocketchat', __( 'Rocket.Chat needs either a User ID next to the auth token, or a personal access token.', 'wp-messenger-forward' ) );

			return false;
		}

		$success = true;

		foreach ( self::split_message( $message, 3500 ) as $chunk ) {
			$payload['text'] = $chunk;

			$response = wp_remote_post(
				$base . '/chat.postMessage',
				array(
					'timeout'     => self::http_timeout(),
					'redirection' => 2,
					'headers'     => $headers,
					'body'        => wp_json_encode( $payload ),
				)
			);

			if ( is_wp_error( $response ) ) {
				self::fail( 'rocketchat', $response->get_error_message() );

				return false;
			}

			$code = (int) wp_remote_retrieve_response_code( $response );
			$body = json_decode( (string) wp_remote_retrieve_body( $response ), true );

			if ( $code < 200 || $code >= 300 || ( is_array( $body ) && isset( $body['success'] ) && ! $body['success'] ) ) {
				self::fail(
					'rocketchat',
					sprintf(
						'HTTP %d — %s',
						$code,
						is_array( $body ) && isset( $body['error'] ) ? (string) $body['error'] : wp_remote_retrieve_response_message( $response )
					)
				);

				$success = false;
				break;
			}
		}

		return $success;
	}

	/**
	 * A test message used by the settings screen.
	 *
	 * @return array<string,bool>
	 */
	public static function send_test_message() {
		return self::send_to_messengers(
			self::build_message(
				'✅ ' . __( 'Test message from WP Messenger Forward', 'wp-messenger-forward' ),
				array(
					'Site' => get_bloginfo( 'name' ),
					'URL'  => home_url( '/' ),
					'Time' => self::format_datetime( self::utc_now() ),
				)
			)
		);
	}

	/* ---------------------------------------------------------------------
	 * Operator replies: pulling them back to the customer
	 * ------------------------------------------------------------------ */

	/**
	 * Extra cron intervals for the reply relay.
	 *
	 * @param array $schedules Registered schedules.
	 * @return array
	 */
	public static function register_cron_schedules( $schedules ) {
		$schedules['wpmf_fast'] = array(
			'interval' => 60,
			'display'  => __( 'Every minute (messenger reply relay)', 'wp-messenger-forward' ),
		);
		$schedules['wpmf_slow'] = array(
			'interval' => 300,
			'display'  => __( 'Every five minutes (messenger reply relay)', 'wp-messenger-forward' ),
		);

		return $schedules;
	}

	/**
	 * (Un)schedule the relay depending on the settings.
	 */
	public static function schedule_relay() {
		if ( ! self::get( 'relay_enabled', false ) ) {
			// Only touch the cron option when something is actually scheduled.
			if ( wp_next_scheduled( self::RELAY_CRON_HOOK ) ) {
				wp_clear_scheduled_hook( self::RELAY_CRON_HOOK );
			}

			return;
		}

		$recurrence = (string) self::get( 'relay_schedule', 'wpmf_fast' );

		if ( ! in_array( $recurrence, array( 'wpmf_fast', 'wpmf_slow' ), true ) ) {
			$recurrence = 'wpmf_fast';
		}

		$next = wp_next_scheduled( self::RELAY_CRON_HOOK );

		if ( $next && $recurrence === wp_get_schedule( self::RELAY_CRON_HOOK ) ) {
			return;
		}

		wp_clear_scheduled_hook( self::RELAY_CRON_HOOK );
		wp_schedule_event( time() + 30, $recurrence, self::RELAY_CRON_HOOK );
	}

	/**
	 * Poll every configured bot for operator replies.
	 */
	public static function relay_incoming_replies() {
		foreach ( array( 'telegram', 'bale' ) as $transport ) {
			if ( '' !== self::bot_token( $transport ) && '' !== self::bot_chat_id( $transport ) ) {
				self::poll_bot_updates( $transport );
			}
		}
	}

	/**
	 * Fetch pending bot updates and route them into the right conversation.
	 *
	 * Replies are matched by the ticket tag that is printed in front of every
	 * forwarded chat message ("#WPMF-A1B2C3"), either because the operator
	 * replied to that message or because they quoted the tag.
	 *
	 * @param string $transport "telegram" or "bale".
	 * @return int Number of ingested replies.
	 */
	private static function poll_bot_updates( $transport ) {
		$offset_key = 'telegram' === $transport ? self::TG_OFFSET_OPTION : self::BALE_OFFSET_OPTION;
		$offset     = (int) get_option( $offset_key, 0 );

		$url = self::bot_api_base( $transport ) . self::bot_token( $transport ) . '/getUpdates';

		$response = self::http_post_json(
			$url,
			array(
				'offset'          => $offset,
				'timeout'         => 0,
				'limit'           => 50,
				'allowed_updates' => array( 'message', 'channel_post', 'edited_message' ),
			),
			$transport
		);

		if ( ! $response['ok'] || empty( $response['body']['result'] ) || ! is_array( $response['body']['result'] ) ) {
			if ( ! $response['ok'] ) {
				self::fail( $transport, 'getUpdates: ' . $response['error'] );
			}

			return 0;
		}

		$bot_id    = self::bot_user_id( $transport );
		$configured = self::bot_chat_id( $transport );
		$ingested  = 0;

		foreach ( $response['body']['result'] as $update ) {
			if ( ! is_array( $update ) ) {
				continue;
			}

			$update_id = isset( $update['update_id'] ) ? (int) $update['update_id'] : 0;

			if ( $update_id >= $offset ) {
				$offset = $update_id + 1;
			}

			$message = array();
			$is_edit  = false;

			foreach ( array( 'message', 'channel_post', 'edited_message' ) as $key ) {
				if ( isset( $update[ $key ] ) && is_array( $update[ $key ] ) ) {
					$message = $update[ $key ];
					$is_edit  = 'edited_message' === $key;
					break;
				}
			}

			if ( empty( $message ) || $is_edit ) {
				continue;
			}

			$from    = isset( $message['from']['id'] ) ? (int) $message['from']['id'] : 0;
			$chat_id = isset( $message['chat']['id'] ) ? (string) $message['chat']['id'] : '';

			// Ignore the bot's own messages and channels we do not own.
			if ( $from > 0 && $from === $bot_id ) {
				continue;
			}

			$text = '';

			if ( isset( $message['text'] ) ) {
				$text = (string) $message['text'];
			} elseif ( isset( $message['caption'] ) ) {
				$text = (string) $message['caption'];
			}

			$text = self::truncate( self::to_plain_text( $text ), 1000 );

			if ( '' === $text ) {
				continue;
			}

			$quoted = isset( $message['reply_to_message']['text'] ) ? (string) $message['reply_to_message']['text'] : '';
			$author = self::telegram_display_name( isset( $message['from'] ) && is_array( $message['from'] ) ? $message['from'] : array() );
			$ticket = self::extract_ticket( $quoted );

			if ( '' === $ticket ) {
				$ticket = self::extract_ticket( $text );
			}

			$conversation = '' !== $ticket ? self::conversation_by_ticket( $ticket ) : null;

			// No ticket tag: only a message that visibly answers one of our
			// forwarded tickets may reach a customer, and only inside the
			// configured channel. Anything else in the group stays private.
			if ( ! $conversation ) {
				$is_reply_to_us = isset( $message['reply_to_message']['text'] ) && false !== strpos( (string) $message['reply_to_message']['text'], 'WPMF-' );

				if ( ! $is_reply_to_us || '' === $configured || $chat_id !== $configured ) {
					continue;
				}

				$conversation = self::most_recent_open_conversation();
			}

			if ( ! $conversation ) {
				continue;
			}

			if ( preg_match( '#^\s*/?(close|end)\b#i', $text ) ) {
				// insert_message() rather than add_agent_message(): the latter
				// reactivates the thread, which would undo this very close.
				self::insert_message( (int) $conversation['id'], 'agent', $author, __( 'This conversation has been closed by an operator on the messenger.', 'wp-messenger-forward' ) );
				self::set_conversation_status( (int) $conversation['id'], 'closed' );
				$ingested++;

				continue;
			}

			self::add_agent_message( (int) $conversation['id'], $author, $text, $chat_id );
			$ingested++;
		}

		update_option( $offset_key, $offset, false );

		return $ingested;
	}

	/**
	 * Display name of a Telegram/Bale "from" object.
	 *
	 * @param array $from Sender payload.
	 * @return string
	 */
	private static function telegram_display_name( array $from ) {
		$name = trim( ( isset( $from['first_name'] ) ? $from['first_name'] : '' ) . ' ' . ( isset( $from['last_name'] ) ? $from['last_name'] : '' ) );

		if ( '' === $name && ! empty( $from['username'] ) ) {
			$name = '@' . $from['username'];
		}

		if ( '' === $name ) {
			$name = __( 'Operator', 'wp-messenger-forward' );
		}

		return self::truncate( self::to_plain_text( $name ), 60 );
	}

	/**
	 * Numeric bot user id, cached for half a day.
	 *
	 * @param string $transport Transport key.
	 * @return int
	 */
	private static function bot_user_id( $transport ) {
		$option    = 'wpmf_bot_id_' . $transport;
		$cached    = get_transient( $option );

		if ( is_numeric( $cached ) ) {
			return (int) $cached;
		}

		$url      = self::bot_api_base( $transport ) . self::bot_token( $transport ) . '/getMe';
		$response = self::http_post_json( $url, array(), $transport );

		if ( $response['ok'] && isset( $response['body']['result']['id'] ) ) {
			$id = (int) $response['body']['result']['id'];
			set_transient( $option, $id, 12 * HOUR_IN_SECONDS );

			return $id;
		}

		return 0;
	}

	/**
	 * Ticket tag printed in forwarded messages.
	 *
	 * @param string $ticket Raw ticket.
	 * @return string
	 */
	public static function ticket_tag( $ticket ) {
		return '#WPMF-' . $ticket;
	}

	/**
	 * Pull a ticket code out of free text.
	 *
	 * @param string $text Text to scan.
	 * @return string Uppercase ticket or an empty string.
	 */
	public static function extract_ticket( $text ) {
		if ( preg_match( '/WPMF-([A-Z0-9]{' . (int) self::TICKET_LENGTH . '})/i', (string) $text, $matches ) ) {
			return strtoupper( $matches[1] );
		}

		return '';
	}

	/**
	 * Fresh, unique ticket code.
	 *
	 * @return string
	 */
	private static function generate_ticket() {
		global $wpdb;

		$alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // No ambiguous I/O/0/1.
		$table    = self::table( 'conversations' );

		for ( $attempt = 0; $attempt < 12; $attempt++ ) {
			$ticket = '';

			for ( $i = 0; $i < self::TICKET_LENGTH; $i++ ) {
				$ticket .= $alphabet[ random_int( 0, strlen( $alphabet ) - 1 ) ];
			}

			$found = $wpdb->get_var( $wpdb->prepare( 'SELECT id FROM $table WHERE ticket = %s LIMIT 1', $ticket ) );

			if ( null === $found ) {
				return $ticket;
			}
		}

		return strtoupper( substr( hash( 'crc32b', (string) microtime( true ) ), 0, self::TICKET_LENGTH ) );
	}

	/**
	 * Register the HTTP endpoint used by Rocket.Chat outgoing webhooks.
	 */
	public static function register_ingest_route() {
		register_rest_route(
			'wp-messenger-forward/v1',
			'/incoming',
			array(
				'methods'             => 'POST',
				'callback'            => array( __CLASS__, 'rest_incoming_reply' ),
				'permission_callback' => '__return_true',
				'args'                => array(
					'ticket' => array( 'type' => 'string', 'required' => true ),
					'text'   => array( 'type' => 'string', 'required' => true ),
					'sender' => array( 'type' => 'string', 'required' => false ),
				),
			)
		);
	}

	/**
	 * Ingest an operator reply coming from Rocket.Chat or any other hook.
	 *
	 * @param WP_REST_Request $request Request.
	 * @return WP_REST_Response|WP_Error
	 */
	public static function rest_incoming_reply( WP_REST_Request $request ) {
		$secret = (string) self::get( 'ingest_secret' );

		if ( '' === $secret ) {
			return new WP_Error( 'wpmf_disabled', __( 'The reply endpoint is disabled: set an ingest secret first.', 'wp-messenger-forward' ), array( 'status' => 403 ) );
		}

		$given = (string) $request->get_param( 'token' );

		if ( '' === $given ) {
			$given = (string) $request->get_header( 'x-wpmf-token' );
		}

		if ( '' === $given || ! hash_equals( $secret, $given ) ) {
			return new WP_Error( 'wpmf_forbidden', __( 'Invalid ingest token.', 'wp-messenger-forward' ), array( 'status' => 401 ) );
		}

		if ( ! self::throttle( 'ingest|' . self::client_ip(), 2 ) ) {
			return new WP_Error( 'wpmf_too_many', __( 'Too many requests.', 'wp-messenger-forward' ), array( 'status' => 429 ) );
		}

		$ticket = self::extract_ticket( (string) $request->get_param( 'ticket' ) );
		$text   = self::truncate( self::to_plain_text( (string) $request->get_param( 'text' ) ), 1000 );
		$author = self::truncate( self::to_plain_text( (string) $request->get_param( 'sender' ) ), 60 );

		if ( '' === $ticket ) {
			return new WP_Error( 'wpmf_no_ticket', __( 'The ticket could not be read from the payload.', 'wp-messenger-forward' ), array( 'status' => 400 ) );
		}

		$conversation = self::conversation_by_ticket( $ticket );

		if ( ! $conversation ) {
			return new WP_Error( 'wpmf_unknown_ticket', __( 'Unknown ticket.', 'wp-messenger-forward' ), array( 'status' => 404 ) );
		}

		$message_id = self::add_agent_message( (int) $conversation['id'], '' !== $author ? $author : __( 'Operator', 'wp-messenger-forward' ), $text );

		return rest_ensure_response(
			array(
				'success'         => true,
				'ticket'          => $ticket,
				'conversation_id' => (int) $conversation['id'],
				'message_id'      => $message_id,
			)
		);
	}

	/* ---------------------------------------------------------------------
	 * Support chat: storage
	 * ------------------------------------------------------------------ */

	/**
	 * Normalise the visitor token that the widget keeps in localStorage.
	 *
	 * @param string $raw Raw token from the request.
	 * @return array{token:string,rotation:bool}
	 */
	private static function normalize_visitor_token( $raw ) {
		$raw = is_scalar( $raw ) ? strtolower( trim( (string) $raw ) ) : '';

		if ( preg_match( '/^[a-f0-9]{32,64}$/', $raw ) ) {
			return array(
				'token'    => $raw,
				'rotation' => false,
			);
		}

		return array(
			'token'    => bin2hex( random_bytes( 16 ) ),
			'rotation' => true,
		);
	}

	/**
	 * Hashed visitor token used as the ownership key of a conversation.
	 *
	 * @param string $token Visitor token.
	 * @return string
	 */
	private static function visitor_key( $token ) {
		return hash( 'sha256', 'wpmf|' . $token );
	}

	/**
	 * The active (not closed) conversation of a visitor.
	 *
	 * @param string $visitor_key Hashed token.
	 * @return array|null
	 */
	private static function conversation_for_visitor( $visitor_key ) {
		global $wpdb;

		$table = self::table( 'conversations' );

		return $wpdb->get_row(
			$wpdb->prepare(
				"SELECT * FROM $table WHERE visitor_key = %s AND status <> 'closed' ORDER BY updated_at DESC, id DESC LIMIT 1",
				$visitor_key
			),
			ARRAY_A
		);
	}

	/**
	 * Look up a conversation by ticket, used by the reply relay.
	 *
	 * @param string $ticket Ticket code.
	 * @return array|null
	 */
	public static function conversation_by_ticket( $ticket ) {
		global $wpdb;

		$table = self::table( 'conversations' );

		return $wpdb->get_row(
			$wpdb->prepare( "SELECT * FROM $table WHERE ticket = %s ORDER BY id DESC LIMIT 1", strtoupper( (string) $ticket ) ),
			ARRAY_A
		);
	}

	/**
	 * The conversation an operator should reply into when they post in the
	 * channel without quoting a ticket.
	 *
	 * @return array|null
	 */
	private static function most_recent_open_conversation() {
		global $wpdb;

		$table = self::table( 'conversations' );

		return $wpdb->get_row(
			$wpdb->prepare( "SELECT * FROM $table WHERE status = %s ORDER BY updated_at DESC, id DESC LIMIT 1", 'open' ),
			ARRAY_A
		);
	}

	/**
	 * Read or create the conversation belonging to a visitor.
	 *
	 * @param string $visitor_key Hashed token.
	 * @param bool   $create      Create one when the visitor has none.
	 * @return array|null
	 */
	private static function conversation_for( $visitor_key, $create = false ) {
		$conversation = self::conversation_for_visitor( $visitor_key );

		if ( $conversation || ! $create ) {
			return $conversation;
		}

		global $wpdb;

		$table = self::table( 'conversations' );
		$now   = self::utc_now();

		$inserted = $wpdb->insert(
			$table,
			array(
				'ticket'        => self::generate_ticket(),
				'visitor_key'   => $visitor_key,
				'status'        => 'open',
				'created_at'    => $now,
				'updated_at'    => $now,
				'origin_chat_id' => self::bot_chat_id( 'telegram' ),
			),
			array( '%s', '%s', '%s', '%s', '%s', '%s' )
		);

		if ( false === $inserted ) {
			self::log( 'Could not create a conversation: ' . (string) $wpdb->last_error );

			return null;
		}

		return $wpdb->get_row(
			$wpdb->prepare( "SELECT * FROM $table WHERE id = %d LIMIT 1", (int) $wpdb->insert_id ),
			ARRAY_A
		);
	}

	/**
	 * Store one chat message.
	 *
	 * @param int    $conversation_id Conversation row id.
	 * @param string $sender          "customer" or "agent".
	 * @param string $author_name     Display name shown in the transcript.
	 * @param string $message         Plain text body.
	 * @param array  $extra           Optional column overrides.
	 * @return int Inserted message id, 0 on failure.
	 */
	private static function insert_message( $conversation_id, $sender, $author_name, $message, array $extra = array() ) {
		global $wpdb;

		$conversation_id = (int) $conversation_id;
		$message         = self::normalize_outgoing( $message );

		if ( $conversation_id < 1 || '' === $message ) {
			return 0;
		}

		$messages = self::table( 'messages' );

		$data = array_merge(
			array(
				'conversation_id' => $conversation_id,
				'sender'          => 'agent' === $sender ? 'agent' : 'customer',
				'author_name'     => self::truncate( (string) $author_name, 120 ),
				'message'         => $message,
				'forwarded'       => 0,
				'created_at'      => self::utc_now(),
			),
			$extra
		);

		$keys   = array_keys( $data );
		$format = array();

		foreach ( $keys as $key ) {
			$format[] = 'conversation_id' === $key || 'forwarded' === $key ? '%d' : '%s';
		}

		if ( false === $wpdb->insert( $messages, $data, $format ) ) {
			self::log( 'Could not store a chat message: ' . (string) $wpdb->last_error );

			return 0;
		}

		$message_id = (int) $wpdb->insert_id;
		$conversations = self::table( 'conversations' );
		$delta        = 'customer' === $data['sender'] ? 1 : 0;

		$wpdb->query(
			$wpdb->prepare(
				"UPDATE $conversations SET last_message_id = %d, updated_at = %s, unread_agents = unread_agents + %d WHERE id = %d",
				$message_id,
				self::utc_now(),
				$delta,
				$conversation_id
			)
		);

		return $message_id;
	}

	/**
	 * Append an operator reply to a conversation, from the relay or the admin.
	 *
	 * @param int    $conversation_id Conversation id.
	 * @param string $author_name     Operator name.
	 * @param string $text            Reply text.
	 * @param string $origin_chat_id  Messenger chat id the reply came from.
	 * @return int
	 */
	public static function add_agent_message( $conversation_id, $author_name, $text, $origin_chat_id = '' ) {
		$message_id = self::insert_message( $conversation_id, 'agent', $author_name, $text );

		if ( $message_id && '' !== $origin_chat_id ) {
			global $wpdb;

			$conversations = self::table( 'conversations' );

			$wpdb->query(
				$wpdb->prepare( "UPDATE $conversations SET origin_chat_id = %s WHERE id = %d", (string) $origin_chat_id, (int) $conversation_id )
			);
		}

		if ( $message_id ) {
			self::set_conversation_status( $conversation_id, 'open' );
		}

		return $message_id;
	}

	/**
	 * Messages of one conversation after a cursor.
	 *
	 * @param int $conversation_id Conversation id.
	 * @param int $after_id        Only messages with a bigger id.
	 * @param int $limit           Row limit.
	 * @return array<int,array>
	 */
	private static function messages_after( $conversation_id, $after_id, $limit = 100 ) {
		global $wpdb;

		$messages = self::table( 'messages' );
		$rows     = $wpdb->get_results(
			$wpdb->prepare(
				"SELECT id, sender, author_name, message, created_at FROM $messages WHERE conversation_id = %d AND id > %d ORDER BY id ASC LIMIT %d",
				(int) $conversation_id,
				(int) $after_id,
				(int) $limit
			),
			ARRAY_A
		);

		return is_array( $rows ) ? $rows : array();
	}

	/**
	 * Newest messages of a conversation, oldest first (used by the admin page).
	 *
	 * @param int $conversation_id Conversation id.
	 * @param int $limit           Row limit.
	 * @return array<int,array>
	 */
	private static function latest_messages( $conversation_id, $limit = 200 ) {
		global $wpdb;

		$messages = self::table( 'messages' );
		$rows     = $wpdb->get_results(
			$wpdb->prepare(
				"SELECT id, sender, author_name, message, created_at FROM $messages WHERE conversation_id = %d ORDER BY id DESC LIMIT %d",
				(int) $conversation_id,
				(int) $limit
			),
			ARRAY_A
		);

		return is_array( $rows ) ? array_reverse( $rows ) : array();
	}

	/**
	 * Mark everything a customer has been shown as read.
	 *
	 * @param int $conversation_id Conversation id.
	 * @param int $cursor          Last message id the customer saw.
	 */
	private static function set_customer_cursor( $conversation_id, $cursor ) {
		global $wpdb;

		$conversations = self::table( 'conversations' );

		$wpdb->query(
			$wpdb->prepare(
				"UPDATE $conversations SET customer_cursor = GREATEST( customer_cursor, %d ) WHERE id = %d",
				(int) $cursor,
				(int) $conversation_id
			)
		);
	}

	/**
	 * Change conversation status.
	 *
	 * @param int    $conversation_id Conversation id.
	 * @param string $status          open|pending|closed.
	 */
	public static function set_conversation_status( $conversation_id, $status ) {
		global $wpdb;

		if ( ! in_array( $status, array( 'open', 'pending', 'closed' ), true ) ) {
			return;
		}

		$conversations = self::table( 'conversations' );

		$wpdb->query(
			$wpdb->prepare(
				"UPDATE $conversations SET status = %s, updated_at = %s, unread_agents = 0 WHERE id = %d",
				$status,
				self::utc_now(),
				(int) $conversation_id
			)
		);
	}

	/**
	 * Store the contact details the widget asked for.
	 *
	 * @param int    $conversation_id Conversation id.
	 * @param string $name            Name.
	 * @param string $email           Email.
	 */
	private static function set_conversation_contact( $conversation_id, $name, $email ) {
		global $wpdb;

		$conversations = self::table( 'conversations' );

		$wpdb->query(
			$wpdb->prepare(
				"UPDATE $conversations SET customer_name = %s, customer_email = %s WHERE id = %d",
				self::truncate( sanitize_text_field( (string) $name ), 190 ),
				sanitize_email( (string) $email ),
				(int) $conversation_id
			)
		);
	}

	/**
	 * Conversations for the admin list, newest activity first.
	 *
	 * @param string $status  Filter by status or empty for all.
	 * @param int    $limit   Page size.
	 * @param int    $offset  Offset.
	 * @param string $search  Ticket / name / email fragment.
	 * @return array<int,array>
	 */
	private static function list_conversations( $status = '', $limit = 20, $offset = 0, $search = '' ) {
		global $wpdb;

		$conversations = self::table( 'conversations' );
		$where         = array( '1=1' );
		$args          = array();

		if ( '' !== $status && in_array( $status, array( 'open', 'pending', 'closed' ), true ) ) {
			$where[] = 'status = %s';
			$args[]  = $status;
		}

		if ( '' !== $search ) {
			$where[] = '(ticket LIKE %s OR customer_name LIKE %s OR customer_email LIKE %s)';
			$like    = '%' . $wpdb->esc_like( $search ) . '%';
			$args    = array_merge( $args, array( $like, $like, $like ) );
		}

		$sql = "SELECT * FROM $conversations WHERE " . implode( ' AND ', $where ) . ' ORDER BY updated_at DESC, id DESC LIMIT %d OFFSET %d';
		$args[] = (int) $limit;
		$args[] = (int) $offset;

		$rows = $wpdb->get_results( $wpdb->prepare( $sql, $args ), ARRAY_A );

		return is_array( $rows ) ? $rows : array();
	}

	/**
	 * Total conversations for a filter, used for pagination.
	 *
	 * @param string $status Status filter.
	 * @param string $search Search fragment.
	 * @return int
	 */
	private static function count_conversations( $status = '', $search = '' ) {
		global $wpdb;

		$conversations = self::table( 'conversations' );
		$where         = array( '1=1' );
		$args          = array();

		if ( '' !== $status && in_array( $status, array( 'open', 'pending', 'closed' ), true ) ) {
			$where[] = 'status = %s';
			$args[]  = $status;
		}

		if ( '' !== $search ) {
			$where[] = '(ticket LIKE %s OR customer_name LIKE %s OR customer_email LIKE %s)';
			$like    = '%' . $wpdb->esc_like( $search ) . '%';
			$args    = array_merge( $args, array( $like, $like, $like ) );
		}

		$sql = 'SELECT COUNT(*) FROM ' . $conversations . ' WHERE ' . implode( ' AND ', $where );

		return $args ? (int) $wpdb->get_var( $wpdb->prepare( $sql, $args ) ) : (int) $wpdb->get_var( $sql );
	}

	/* ---------------------------------------------------------------------
	 * Support chat: HTTP endpoints
	 * ------------------------------------------------------------------ */

	/**
	 * Guard shared by both AJAX handlers.
	 *
	 * @return array{token:string,visitor_key:string,rotation:bool}
	 */
	private static function guard_chat_request() {
		check_ajax_referer( self::NONCE_CHAT, 'nonce' );

		if ( ! self::chat_tables_exist() ) {
			wp_send_json_error(
				array( 'message' => __( 'The support chat is not installed yet. Reactivate the plugin to create its tables.', 'wp-messenger-forward' ) ),
				503
			);
		}

		$visitor = self::normalize_visitor_token( isset( $_POST['visitor'] ) ? wp_unslash( $_POST['visitor'] ) : '' );

		return array(
			'token'       => $visitor['token'],
			'visitor_key' => self::visitor_key( $visitor['token'] ),
			'rotation'    => $visitor['rotation'],
		);
	}

	/**
	 * Accept a customer message and forward it as a ticket.
	 */
	public static function ajax_send_message() {
		if ( ! self::get( 'chat_enabled', true ) ) {
			wp_send_json_error( array( 'message' => __( 'The support chat is disabled.', 'wp-messenger-forward' ) ), 403 );
		}

		$context  = self::guard_chat_request();
		$message  = isset( $_POST['message'] ) ? self::truncate( self::to_plain_text( wp_unslash( $_POST['message'] ) ), 2000 ) : '';

		if ( '' === $message ) {
			wp_send_json_error( array( 'message' => __( 'Write a message first.', 'wp-messenger-forward' ) ), 400 );
		}

		self::check_rate_limit( $context['visitor_key'] );

		$conversation = self::conversation_for( $context['visitor_key'], true );

		if ( ! $conversation ) {
			wp_send_json_error( array( 'message' => __( 'The conversation could not be opened. Please try again.', 'wp-messenger-forward' ) ), 500 );
		}

		$name  = isset( $_POST['name'] ) ? sanitize_text_field( wp_unslash( $_POST['name'] ) ) : '';
		$email = isset( $_POST['email'] ) ? sanitize_email( wp_unslash( $_POST['email'] ) ) : '';

		if ( '' !== $email && ! is_email( $email ) ) {
			wp_send_json_error( array( 'message' => __( 'That email address is not valid.', 'wp-messenger-forward' ) ), 400 );
		}

		if ( '' !== $name || '' !== $email ) {
			self::set_conversation_contact( (int) $conversation['id'], $name, $email );
			$conversation['customer_name']  = self::truncate( $name, 190 );
			$conversation['customer_email'] = $email;
		}

		$message_id = self::insert_message( (int) $conversation['id'], 'customer', (string) $conversation['customer_name'], $message );

		if ( ! $message_id ) {
			wp_send_json_error( array( 'message' => __( 'Your message could not be saved. Please try again.', 'wp-messenger-forward' ) ), 500 );
		}

		$forwarded = false;

		if ( self::event_enabled( 'forward_chat_message' ) && self::has_transport() ) {
			$results = self::send_to_messengers(
				self::build_message(
					'💬 ' . __( 'New support message', 'wp-messenger-forward' ) . ' ' . self::ticket_tag( (string) $conversation['ticket'] ),
					array(
						'Ticket'   => self::ticket_tag( (string) $conversation['ticket'] ),
						'Name'     => (string) $conversation['customer_name'],
						'Email'    => (string) $conversation['customer_email'],
						'Site'     => get_bloginfo( 'name' ),
						'Page'     => self::safe_url( wp_get_referer() ),
						'IP'       => self::client_ip(),
						'User'     => is_user_logged_in() ? wp_get_current_user()->user_login : __( 'Guest', 'wp-messenger-forward' ),
						'Reply in' => admin_url( 'admin.php?page=wp-messenger-forward-chat&conversation=' . (int) $conversation['id'] ),
						'Language' => get_locale(),
					),
					array( $message )
				)
			);

			// Only claim the ticket is on its way when a transport took it.
			$forwarded = in_array( true, $results, true );

			if ( $forwarded ) {
				global $wpdb;
				$messages = self::table( 'messages' );
				$wpdb->query( $wpdb->prepare( "UPDATE $messages SET forwarded = 1 WHERE id = %d", $message_id ) );
			}
		}

		wp_send_json_success(
			array(
				'id'          => $message_id,
				'ticket'      => self::ticket_tag( (string) $conversation['ticket'] ),
				'forwarded'   => $forwarded,
				'visitor'     => $context['token'],
				'created_at'  => self::utc_now(),
				'notice'      => $forwarded
					? __( 'Sent. We will answer here.', 'wp-messenger-forward' )
					: __( 'Sent.', 'wp-messenger-forward' ),
			)
		);
	}

	/**
	 * Simple per-visitor flood guard.
	 *
	 * @param string $visitor_key Hashed visitor token.
	 */
	private static function check_rate_limit( $visitor_key ) {
		$limit  = (int) max( 1, (int) self::get( 'chat_rate_limit', 8 ) );
		$window = (int) max( 10, (int) self::get( 'chat_rate_window', 60 ) );
		$bucket = 'wpmf_rl_' . $visitor_key;
		$count  = (int) get_transient( $bucket );

		if ( $count >= $limit ) {
			wp_send_json_error(
				array(
					'message' => sprintf(
						/* translators: %d: number of seconds. */
						__( 'You are sending messages too fast. Please wait %d seconds.', 'wp-messenger-forward' ),
						$window
					),
					'retry'   => $window,
				),
				429
			);
		}

		set_transient( $bucket, $count + 1, $window );
	}

	/**
	 * Return agent messages the customer has not seen yet.
	 */
	public static function ajax_poll_messages() {
		$context = self::guard_chat_request();
		$after   = isset( $_POST['after'] ) ? absint( wp_unslash( $_POST['after'] ) ) : 0;

		$conversation = self::conversation_for_visitor( $context['visitor_key'] );

		if ( ! $conversation ) {
			wp_send_json_success(
				array(
					'messages' => array(),
					'after'    => $after,
					'visitor'  => $context['token'],
					'status'   => 'none',
				)
			);
		}

		$rows     = self::messages_after( (int) $conversation['id'], $after, 60 );
		$messages = array();
		$cursor   = $after;

		foreach ( $rows as $row ) {
			$cursor = (int) $row['id'];

			$messages[] = array(
				'id'     => (int) $row['id'],
				'sender' => 'agent' === $row['sender'] ? 'agent' : 'customer',
				'author' => (string) $row['author_name'],
				'text'   => (string) $row['message'],
				'time'   => self::format_datetime( (string) $row['created_at'] ),
			);
		}

		if ( $cursor > $after ) {
			self::set_customer_cursor( (int) $conversation['id'], $cursor );
		}

		wp_send_json_success(
			array(
				'messages' => $messages,
				'after'    => $cursor,
				'ticket'   => self::ticket_tag( (string) $conversation['ticket'] ),
				'status'   => (string) $conversation['status'],
				'visitor'  => $context['token'],
			)
		);
	}

	/* ---------------------------------------------------------------------
	 * Support chat: frontend widget
	 * ------------------------------------------------------------------ */

	/**
	 * Shortcode: [customer_chat]
	 *
	 * Renders the widget and prints its assets once per page. Everything is
	 * plain DOM work: the plugin must not assume that jQuery is loaded on the
	 * front end, which is exactly what broke the 2.0 widget.
	 *
	 * @param array $atts Shortcode attributes.
	 * @return string
	 */
	public static function customer_chat_shortcode( $atts = array() ) {
		$settings = self::get_settings();

		if ( empty( $settings['chat_enabled'] ) ) {
			return '';
		}

		if ( ! self::chat_tables_exist() ) {
			return current_user_can( 'manage_options' )
				? '<div class="wpmf-chat-notice">' . esc_html__( 'Support chat: the plugin tables are missing, reactivate WP Messenger Forward to create them.', 'wp-messenger-forward' ) . '</div>'
				: '';
		}

		if ( self::$chat_rendered ) {
			return '<!-- WP Messenger Forward: [customer_chat] is already rendered on this page. -->';
		}

		self::$chat_rendered = true;

		$atts = shortcode_atts(
			array(
				'title'    => $settings['chat_title'],
				'intro'    => $settings['chat_intro'],
				'launcher' => __( 'Need help?', 'wp-messenger-forward' ),
				'align'    => 'right',
			),
			is_array( $atts ) ? $atts : array(),
			'customer_chat'
		);

		$align    = in_array( $atts['align'], array( 'left', 'right' ), true ) ? $atts['align'] : 'right';
		$labels   = array(
			'title'       => wp_strip_all_tags( (string) $atts['title'] ),
			'intro'       => wp_strip_all_tags( (string) $atts['intro'] ),
			'launcher'    => wp_strip_all_tags( (string) $atts['launcher'] ),
			'aria'        => __( 'Support chat', 'wp-messenger-forward' ),
			'close'       => __( 'Close', 'wp-messenger-forward' ),
			'name'        => __( 'Your name', 'wp-messenger-forward' ),
			'email'       => __( 'Your email', 'wp-messenger-forward' ),
			'placeholder' => __( 'Type your message…', 'wp-messenger-forward' ),
			'send'        => __( 'Send', 'wp-messenger-forward' ),
			'sending'     => __( 'Sending…', 'wp-messenger-forward' ),
			'you'         => __( 'You', 'wp-messenger-forward' ),
			'team'        => __( 'Support', 'wp-messenger-forward' ),
			'error'       => __( 'Something went wrong. Please try again.', 'wp-messenger-forward' ),
			'closed'      => __( 'This conversation is closed. Write a message to start a new one.', 'wp-messenger-forward' ),
			'offline'     => __( 'The team is offline right now — leave a message anyway.', 'wp-messenger-forward' ),
			'askContact'  => (bool) $settings['chat_ask_contact'],
		);
		$config   = array(
			'ajaxUrl'      => admin_url( 'admin-ajax.php' ),
			'nonce'        => wp_create_nonce( self::NONCE_CHAT ),
			'pollSeconds'  => (int) max( 3, (int) $settings['chat_poll_seconds'] ),
			'askContact'   => (bool) $settings['chat_ask_contact'],
			'forwards'     => self::has_transport() && self::event_enabled( 'forward_chat_message' ),
			'labels'       => $labels,
		);
		$ticket   = '';
		$contact  = $labels['askContact'];

		ob_start();
		?>
		<div class="wpmf-chat wpmf-chat--<?php echo esc_attr( $align ); ?>" id="wpmf-chat" data-widget="wpmf">
			<button type="button" class="wpmf-chat__launcher" data-ref="launcher" aria-expanded="false" aria-controls="wpmf-panel">
				<span class="wpmf-chat__launcher-icon" aria-hidden="true">&#128172;</span>
				<span class="wpmf-chat__launcher-text"><?php echo esc_html( $labels['launcher'] ); ?></span>
				<span class="wpmf-chat__badge" data-ref="badge" hidden>0</span>
			</button>

			<div class="wpmf-chat__panel" id="wpmf-panel" role="dialog" aria-label="<?php echo esc_attr( $labels['aria'] ); ?>" hidden>
				<div class="wpmf-chat__header">
					<div class="wpmf-chat__heading">
						<span class="wpmf-chat__title"><?php echo esc_html( $labels['title'] ); ?></span>
						<span class="wpmf-chat__ticket" data-ref="ticket"><?php echo esc_html( $ticket ); ?></span>
					</div>
					<button type="button" class="wpmf-chat__close" data-ref="close" aria-label="<?php echo esc_attr( $labels['close'] ); ?>">&#215;</button>
				</div>

				<div class="wpmf-chat__log" data-ref="log" role="log" aria-live="polite">
					<p class="wpmf-chat__intro"><?php echo esc_html( $labels['intro'] ); ?></p>
				</div>

				<form class="wpmf-chat__form" data-ref="form" autocomplete="off">
					<?php if ( $contact ) : ?>
						<div class="wpmf-chat__contact">
							<label class="wpmf-chat__field">
								<span><?php echo esc_html( $labels['name'] ); ?></span>
								<input type="text" name="name" data-ref="name" maxlength="120" value="">
							</label>
							<label class="wpmf-chat__field">
								<span><?php echo esc_html( $labels['email'] ); ?></span>
								<input type="email" name="email" data-ref="email" maxlength="160" value="">
							</label>
						</div>
					<?php endif; ?>

					<label class="wpmf-chat__visually-hidden" for="wpmf-message"><?php echo esc_html( $labels['placeholder'] ); ?></label>
					<div class="wpmf-chat__composer">
						<textarea id="wpmf-message" data-ref="input" rows="1" maxlength="2000" placeholder="<?php echo esc_attr( $labels['placeholder'] ); ?>"></textarea>
						<button type="submit" class="wpmf-chat__send" data-ref="send"><?php echo esc_html( $labels['send'] ); ?></button>
					</div>
					<p class="wpmf-chat__status" data-ref="status" role="status" aria-live="polite"></p>
				</form>
			</div>
		</div>
		<noscript>
			<p class="wpmf-chat__noscript">
				<?php
				printf(
					/* translators: %s: site email address. */
					esc_html__( 'The support chat needs JavaScript. You can also write to %s.', 'wp-messenger-forward' ),
					esc_html( get_bloginfo( 'admin_email' ) )
				);
				?>
			</p>
		</noscript>
		<style id="wpmf-chat-css"><?php echo self::chat_css(); // phpcs:ignore WordPress.Security.EscapeOutput -- static CSS. ?></style>
		<script id="wpmf-chat-config">window.wpmfChatConfig=<?php echo self::json_for_html( $config ); ?>;</script>
		<script id="wpmf-chat-js"><?php echo self::chat_js(); // phpcs:ignore WordPress.Security.EscapeOutput -- static JS. ?></script>
		<?php

		return (string) ob_get_clean();
	}

	/**
	 * JSON that can never break out of a <script> tag.
	 *
	 * @param mixed $data Data.
	 * @return string
	 */
	private static function json_for_html( $data ) {
		$json = wp_json_encode( $data );

		if ( ! is_string( $json ) ) {
			return 'null';
		}

		return str_replace(
			array( '<', '>', '&' ),
			array( '\u003C', '\u003E', '\u0026' ),
			$json
		);
	}

