	/**
	 * Widget runtime: open/close, send, incremental polling, unread badge.
	 *
	 * @return string
	 */
	public static function chat_js() {
		return <<<'JS'
(function () {
	'use strict';

	var root = document.querySelector('[data-widget="wpmf"]');
	if (!root) { return; }

	var cfg = window.wpmfChatConfig || {};
	var labels = cfg.labels || {};
	var ref = {};

	Array.prototype.forEach.call(root.querySelectorAll('[data-ref]'), function (node) {
		ref[node.getAttribute('data-ref')] = node;
	});

	var log = ref.log;
	var form = ref.form;
	var input = ref.input;
	var sendBtn = ref.send;
	var status = ref.status;
	var badge = ref.badge;
	var panel = document.getElementById('wpmf-panel');

	var state = {
		open: false,
		busy: false,
		after: 0,
		token: readToken(),
		timer: null,
		unread: 0,
		pollSeconds: Math.max(3, cfg.pollSeconds || 7)
	};

	function readToken() {
		try { return window.localStorage.getItem('wpmfVisitor') || ''; } catch (e) { return ''; }
	}

	function saveToken(token) {
		if (!token) { return; }
		try { window.localStorage.setItem('wpmfVisitor', token); } catch (e) {}
	}

	function readDraft(key) {
		try { return window.localStorage.getItem(key) || ''; } catch (e) { return ''; }
	}

	function saveDraft(key, value) {
		try { window.localStorage.setItem(key, value || ''); } catch (e) {}
	}

	function setText(node, value) {
		if (node) { node.textContent = value; }
	}

	function say(message, isError) {
		setText(status, message || '');
		if (status) { status.setAttribute('data-state', isError ? 'error' : 'info'); }
	}

	function request(action, data) {
		var body = new FormData();
		body.append('action', action);
		body.append('nonce', cfg.nonce || '');
		body.append('visitor', state.token);

		Object.keys(data || {}).forEach(function (key) {
			body.append(key, data[key]);
		});

		return window.fetch(cfg.ajaxUrl, {
			method: 'POST',
			credentials: 'same-origin',
			body: body
		}).then(function (response) {
			return response.json().catch(function () {
				return { success: false, data: { message: labels.error || '' } };
			});
		});
	}

	function bubble(sender, author, text, time) {
		var wrap = document.createElement('p');
		wrap.className = 'wpmf-chat__msg ' + ('customer' === sender ? 'wpmf-chat__msg--me' : 'wpmf-chat__msg--them');

		var meta = document.createElement('span');
		meta.className = 'wpmf-chat__meta';
		meta.textContent = [author || ('customer' === sender ? labels.you : labels.team), time].filter(Boolean).join(' · ');

		var body = document.createElement('span');
		body.textContent = text;

		wrap.appendChild(meta);
		wrap.appendChild(body);
		log.appendChild(wrap);
		log.scrollTop = log.scrollHeight;
		return wrap;
	}

	function system(text) {
		var node = document.createElement('p');
		node.className = 'wpmf-chat__msg wpmf-chat__msg--system';
		node.textContent = text;
		log.appendChild(node);
		log.scrollTop = log.scrollHeight;
	}

	function setUnread(count) {
		state.unread = count;
		if (!badge) { return; }
		badge.textContent = String(count);
		badge.hidden = count < 1 || state.open;
	}

	function fill(message) {
		var text = message && message.text ? message.text : '';
		bubble(message.sender, message.author, text, message.time);
	}

	function ingest(payload) {
		if (!payload || !payload.success) {
			return;
		}

		var data = payload.data || {};

		saveToken(data.visitor || state.token);
		state.token = data.visitor || state.token;

		if (data.ticket) { setText(ref.ticket, data.ticket); }

		(data.messages || []).forEach(function (message) {
			if (parseInt(message.id, 10) > state.after) {
				state.after = parseInt(message.id, 10);
			}
			fill(message);
			if (!state.open && 'agent' === message.sender) { setUnread(state.unread + 1); }
		});

		if ('closed' === data.status) {
			system(labels.closed || '');
		}
	}

	function poll() {
		if (!state.token) { return; }

		request('wpmf_poll_messages', { after: state.after }).then(ingest).catch(function () {});
	}

	function schedule() {
		window.clearTimeout(state.timer);

		if (document.hidden) { return; }

		state.timer = window.setTimeout(function () {
			poll();
			schedule();
		}, state.pollSeconds * 1000);
	}

	function setOpen(isOpen) {
		state.open = isOpen;
		panel.hidden = !isOpen;
		ref.launcher.setAttribute('aria-expanded', isOpen ? 'true' : 'false');

		if (isOpen) {
			setUnread(0);
			input.focus();
			poll();
			schedule();
		} else {
			window.clearTimeout(state.timer);
			ref.launcher.focus();
		}
	}

	function submit(event) {
		if (event) { event.preventDefault(); }

		var text = (input.value || '').trim();

		if (!text || state.busy) { return; }

		var name = ref.name ? ref.name.value.trim() : readDraft('wpmfName');
		var email = ref.email ? ref.email.value.trim() : readDraft('wpmfEmail');

		state.busy = true;
		sendBtn.disabled = true;
		say(labels.sending || 'Sending…', false);

		var payload = { message: text };

		if (name) { payload.name = name; saveDraft('wpmfName', name); }
		if (email) { payload.email = email; saveDraft('wpmfEmail', email); }

		request('wpmf_send_message', payload).then(function (res) {
			if (res && res.success) {
				var data = res.data || {};
				input.value = '';
				state.after = Math.max(state.after, parseInt(data.id, 10) || 0);
				bubble('customer', labels.you, text, '');
				setText(ref.ticket, data.ticket || '');
				say(data.notice || '', false);
				schedule();
			} else {
				var message = (res && res.data && res.data.message) ? res.data.message : (labels.error || 'Error');
				say(message, true);
			}
		}).catch(function () {
			say(labels.error || 'Error', true);
		}).then(function () {
			state.busy = false;
			sendBtn.disabled = false;
			input.focus();
		});
	}

	if (ref.name && readDraft('wpmfName')) { ref.name.value = readDraft('wpmfName'); }
	if (ref.email && readDraft('wpmfEmail')) { ref.email.value = readDraft('wpmfEmail'); }

	ref.launcher.addEventListener('click', function () { setOpen(!state.open); });
	ref.close.addEventListener('click', function () { setOpen(false); });
	form.addEventListener('submit', submit);

	input.addEventListener('keydown', function (event) {
		if ('Enter' === event.key && !event.shiftKey) {
			event.preventDefault();
			submit(event);
		}
	});

	document.addEventListener('keydown', function (event) {
		if ('Escape' === event.key && state.open) { setOpen(false); }
	});

	document.addEventListener('visibilitychange', function () {
		if (document.hidden) { window.clearTimeout(state.timer); return; }
		if (state.open) { poll(); schedule(); }
	});

	if (state.token) { poll(); }
	if (cfg.forwards === false) { system(labels.offline || ''); }
})();
JS;
	}

	/* ---------------------------------------------------------------------
	 * Admin: settings screen
	 * ------------------------------------------------------------------ */

	/**
	 * Boolean settings, used to interpret missing checkboxes on save.
	 *
	 * @return array<int,string>
	 */
	private static function checkbox_keys() {
		$keys = array();

		foreach ( self::defaults() as $key => $default ) {
			if ( is_bool( $default ) ) {
				$keys[] = $key;
			}
		}

		return $keys;
	}

	/**
	 * One <tr> with a labelled input.
	 *
	 * @param string $type  Input type.
	 * @param string $name  Field name.
	 * @param string $label Field label.
	 * @param mixed  $value Current value.
	 * @param string $help  Inline help.
	 * @param array  $attrs Extra attributes as attribute => value.
	 */
	private static function render_row( $type, $name, $label, $value, $help = '', array $attrs = array() ) {
		$id    = 'wpmf-' . $name;
		$extra = '';

		foreach ( $attrs as $key => $attr_value ) {
			$extra .= ' ' . sanitize_key( $key ) . '="' . esc_attr( (string) $attr_value ) . '"';
		}

		printf( '<tr><th scope="row"><label for="%1$s">%2$s</label></th><td>', esc_attr( $id ), esc_html( $label ) );

		if ( 'checkbox' === $type ) {
			printf(
				'<input type="checkbox" id="%1$s" name="%2$s" value="1" %3$s%4$s>',
				esc_attr( $id ),
				esc_attr( $name ),
				checked( (bool) $value, true, false ),
				$extra // phpcs:ignore -- built from escaped attributes above.
			);
		} elseif ( 'textarea' === $type ) {
			printf(
				'<textarea id="%1$s" name="%2$s" rows="3" class="large-text code"%3$s>%4$s</textarea>',
				esc_attr( $id ),
				esc_attr( $name ),
				$extra, // phpcs:ignore -- built from escaped attributes above.
				esc_textarea( (string) $value )
			);
		} else {
			printf(
				'<input type="%1$s" id="%2$s" name="%3$s" value="%4$s" class="regular-text"%5$s>',
				esc_attr( $type ),
				esc_attr( $id ),
				esc_attr( $name ),
				esc_attr( (string) $value ),
				$extra // phpcs:ignore -- built from escaped attributes above.
			);
		}

		if ( '' !== $help ) {
			printf( '<p class="description">%s</p>', esc_html( $help ) );
		}

		echo '</td></tr>';
	}

	/**
	 * One <tr> with a select box.
	 *
	 * @param string $name   Field name.
	 * @param string $label  Label.
	 * @param string $value  Current value.
	 * @param array  $choices value => label.
	 * @param string $help   Inline help.
	 */
	private static function render_select_row( $name, $label, $value, array $choices, $help = '' ) {
		$id = 'wpmf-' . $name;

		printf( '<tr><th scope="row"><label for="%1$s">%2$s</label></th><td><select id="%1$s" name="%3$s">', esc_attr( $id ), esc_html( $label ), esc_attr( $name ) );

		foreach ( $choices as $option => $option_label ) {
			printf(
				'<option value="%s"%s>%s</option>',
				esc_attr( $option ),
				selected( (string) $value, (string) $option, false ),
				esc_html( $option_label )
			);
		}

		echo '</select>';

		if ( '' !== $help ) {
			printf( '<p class="description">%s</p>', esc_html( $help ) );
		}

		echo '</td></tr>';
	}

	/**
	 * Render the settings page.
	 */
	public static function settings_page() {
		if ( ! current_user_can( 'manage_options' ) ) {
			wp_die( esc_html__( 'You are not allowed to change these settings.', 'wp-messenger-forward' ) );
		}

		$settings   = self::get_settings();
		$last_error = get_option( self::LAST_ERROR_OPTION );
		$notice     = self::pull_admin_notice();
		$next_run   = wp_next_scheduled( self::RELAY_CRON_HOOK );
		$chat_count = self::chat_tables_exist() ? self::count_conversations( 'open' ) : 0;
		echo '<div class="wrap">';
		echo '<h1>' . esc_html__( 'Messenger Forward Settings', 'wp-messenger-forward' ) . '</h1>';

		self::render_admin_notice( $notice );

		if ( ! self::has_transport() ) {
			printf(
				'<div class="notice notice-warning"><p>%s</p></div>',
				esc_html__( 'No messenger is configured yet, so nothing will be forwarded. Fill in at least one of the sections below.', 'wp-messenger-forward' )
			);
		}

		if ( is_array( $last_error ) && ! empty( $last_error['error'] ) ) {
			printf(
				'<div class="notice notice-error"><p>%s</p></div>',
				esc_html(
					sprintf(
						/* translators: 1: transport, 2: error, 3: time. */
						'Last delivery failure (%1$s at %2$s): %3$s',
						(string) $last_error['transport'],
						self::format_datetime( (string) $last_error['time'] ),
						(string) $last_error['error']
					)
				)
			);
		}

		echo '<p><a class="button" href="' . esc_url( admin_url( 'admin.php?page=wp-messenger-forward-chat' ) ) . '">' . esc_html( sprintf( 'Open support inbox (%d)', (int) $chat_count ) ) . '</a></p>';

		echo '<form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '">';
		wp_nonce_field( 'wpmf_save_settings', 'wpmf_settings_nonce' );
		echo '<input type="hidden" name="action" value="wpmf_save_settings">';

		echo '<h2 class="title">' . esc_html__( 'Messenger credentials', 'wp-messenger-forward' ) . '</h2>';
		echo '<p class="description">' . esc_html__( 'A messenger is used as soon as both its fields are filled in. Leave a token empty to disable that transport.', 'wp-messenger-forward' ) . '</p>';
		echo '<table class="form-table" role="presentation">';
		self::render_row( 'text', 'telegram_bot_token', __( 'Telegram bot token', 'wp-messenger-forward' ), $settings['telegram_bot_token'], '123456789:ABCdefGHIjkLmnoPQRstU' );
		self::render_row( 'text', 'telegram_chat_id', __( 'Telegram chat or channel ID', 'wp-messenger-forward' ), $settings['telegram_chat_id'], 'Use @channelname, 123456 or -1001234567890 for groups.' );
		self::render_row( 'text', 'bale_bot_token', __( 'Bale bot token', 'wp-messenger-forward' ), $settings['bale_bot_token'], 'Same format as Telegram, sent to api.bale.ai.' );
		self::render_row( 'text', 'bale_chat_id', __( 'Bale chat or channel ID', 'wp-messenger-forward' ), $settings['bale_chat_id'] );
		self::render_row( 'text', 'rocketchat_url', __( 'Rocket.Chat API URL', 'wp-messenger-forward' ), $settings['rocketchat_url'], 'https://chat.example.com/api/v1 — the suffix is added for you.' );
		self::render_row( 'text', 'rocketchat_room', __( 'Rocket.Chat channel or room ID', 'wp-messenger-forward' ), $settings['rocketchat_room'], '#support, @username or a roomId — never a placeholder.' );
		self::render_row( 'text', 'rocketchat_user', __( 'Rocket.Chat user ID', 'wp-messenger-forward' ), $settings['rocketchat_user'], 'Leave empty when you paste a personal access token instead.' );
		self::render_row( 'text', 'rocketchat_token', __( 'Rocket.Chat auth token', 'wp-messenger-forward' ), $settings['rocketchat_token'] );
		echo '</table>';

		echo '<h2 class="title">' . esc_html__( 'Events to forward', 'wp-messenger-forward' ) . '</h2>';
		echo '<table class="form-table" role="presentation">';
		echo '<tr><th scope="row">' . esc_html__( 'Enabled events', 'wp-messenger-forward' ) . '</th><td><fieldset>';

		foreach ( self::event_definitions() as $event => $conf ) {
			printf(
				'<label style="display:block;margin:0 0 6px;"><input type="checkbox" name="events[%1$s]" value="1"%2$s> %3$s</label>',
				esc_attr( $event ),
				checked( ! empty( $settings['events'][ $event ] ), true, false ),
				esc_html( $conf['label'] )
			);
		}

		echo '</fieldset>';

		if ( ! self::is_woocommerce_active() ) {
			echo '<p class="description">' . esc_html__( 'WooCommerce is not active, its events stay silent until it is installed.', 'wp-messenger-forward' ) . '</p>';
		}

		echo '</td></tr>';
		echo '</table>';

		echo '<h2 class="title">' . esc_html__( 'Message format', 'wp-messenger-forward' ) . '</h2>';
		echo '<table class="form-table" role="presentation">';
		self::render_row( 'number', 'excerpt_length', __( 'Excerpt length', 'wp-messenger-forward' ), $settings['excerpt_length'], 'Characters of post or comment content included per message.', array( 'min' => 80, 'max' => 4000, 'step' => 10 ) );
		self::render_row( 'number', 'http_timeout', __( 'HTTP timeout', 'wp-messenger-forward' ), $settings['http_timeout'], 'Seconds before a messenger request is abandoned.', array( 'min' => 3, 'max' => 60 ) );
		self::render_row( 'checkbox', 'disable_web_page_preview', __( 'Disable link previews', 'wp-messenger-forward' ), $settings['disable_web_page_preview'] );
		self::render_row( 'checkbox', 'log_errors', __( 'Log delivery errors with error_log()', 'wp-messenger-forward' ), $settings['log_errors'] );
		self::render_row( 'text', 'status_post_types', __( 'Post types watched for status changes', 'wp-messenger-forward' ), implode( ',', (array) $settings['status_post_types'] ), 'Comma separated, e.g. post,page.' );
		self::render_row( 'text', 'view_post_types', __( 'Post types counted as page views', 'wp-messenger-forward' ), implode( ',', (array) $settings['view_post_types'] ), 'Comma separated, e.g. post,page,product.' );
		self::render_row( 'number', 'view_dedupe_seconds', __( 'View dedupe window', 'wp-messenger-forward' ), $settings['view_dedupe_seconds'], 'One view message per visitor and page inside this many seconds.', array( 'min' => 60, 'max' => 86400, 'step' => 60 ) );
		self::render_row( 'checkbox', 'exclude_admin_views', __( 'Ignore views by administrators', 'wp-messenger-forward' ), $settings['exclude_admin_views'] );
		echo '</table>';

		echo '<h2 class="title">' . esc_html__( 'Customer support chat', 'wp-messenger-forward' ) . '</h2>';
		echo '<table class="form-table" role="presentation">';
		self::render_row( 'checkbox', 'chat_enabled', __( 'Enable the [customer_chat] widget', 'wp-messenger-forward' ), $settings['chat_enabled'] );
		self::render_row( 'text', 'chat_title', __( 'Chat title', 'wp-messenger-forward' ), $settings['chat_title'] );
		self::render_row( 'textarea', 'chat_intro', __( 'Greeting shown before the first message', 'wp-messenger-forward' ), $settings['chat_intro'] );
		self::render_row( 'checkbox', 'chat_ask_contact', __( 'Ask customers for name and email', 'wp-messenger-forward' ), $settings['chat_ask_contact'] );
		self::render_row( 'number', 'chat_poll_seconds', __( 'Reply check interval', 'wp-messenger-forward' ), $settings['chat_poll_seconds'], 'Seconds the widget waits between two polls.', array( 'min' => 3, 'max' => 120 ) );
		self::render_row( 'number', 'chat_rate_limit', __( 'Messages per window', 'wp-messenger-forward' ), $settings['chat_rate_limit'], 'Sends are blocked after this many messages inside the window.', array( 'min' => 1, 'max' => 60 ) );
		self::render_row( 'number', 'chat_rate_window', __( 'Rate limit window', 'wp-messenger-forward' ), $settings['chat_rate_window'], 'Seconds.', array( 'min' => 10, 'max' => 3600 ) );
		echo '</table>';

		echo '<h2 class="title">' . esc_html__( 'Relaying operator replies', 'wp-messenger-forward' ) . '</h2>';
		echo '<table class="form-table" role="presentation">';
		self::render_row( 'checkbox', 'relay_enabled', __( 'Poll Telegram/Bale for replies', 'wp-messenger-forward' ), $settings['relay_enabled'], 'Requires WP-Cron and a bot with group privacy mode disabled. Operators reply to the forwarded message: the ticket tag maps the answer back to the right customer.' );
		self::render_select_row( 'relay_schedule', __( 'Relay frequency', 'wp-messenger-forward' ), $settings['relay_schedule'], array( 'wpmf_fast' => __( 'Every minute', 'wp-messenger-forward' ), 'wpmf_slow' => __( 'Every five minutes', 'wp-messenger-forward' ) ) );
		self::render_row( 'text', 'ingest_secret', __( 'HTTP ingest secret', 'wp-messenger-forward' ), $settings['ingest_secret'], 'For Rocket.Chat or external hooks POSTing to ' . rest_url( 'wp-messenger-forward/v1/incoming' ) . '.' );
		echo '<tr><th scope="row">' . esc_html__( 'Relay status', 'wp-messenger-forward' ) . '</th><td>';

		if ( $next_run ) {
			printf(
				esc_html__( 'Next check: %s', 'wp-messenger-forward' ),
				esc_html( date_i18n( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), (int) $next_run ) )
			);
		} else {
			echo '<em>' . esc_html__( 'Not scheduled — enable the relay above.', 'wp-messenger-forward' ) . '</em>';
		}

		if ( defined( 'DISABLE_WP_CRON' ) && DISABLE_WP_CRON ) {
			echo ' <strong>' . esc_html__( 'DISABLE_WP_CRON is set on this site, so the relay only runs when you trigger cron yourself.', 'wp-messenger-forward' ) . '</strong>';
		}

		echo '</td></tr>';
		echo '</table>';

		echo '<p class="submit">';
		echo '<button type="submit" name="wpmf_save" value="1" class="button button-primary">' . esc_html__( 'Save Changes', 'wp-messenger-forward' ) . '</button> ';
		echo '<button type="submit" name="wpmf_test" value="1" class="button">' . esc_html__( 'Save and send a test message', 'wp-messenger-forward' ) . '</button>';
		echo '</p>';
		echo '</form>';
		echo '</div>';
	}

	/**
	 * Show a one-shot admin notice stored in a transient.
	 *
	 * @param array|null $notice Notice payload.
	 */
	private static function render_admin_notice( $notice ) {
		if ( ! is_array( $notice ) || empty( $notice['message'] ) ) {
			return;
		}

		$level = in_array( $notice['level'], array( 'success', 'error', 'warning', 'info' ), true ) ? $notice['level'] : 'info';

		echo '<div class="notice notice-' . esc_attr( $level ) . ' is-dismissible"><p>' . esc_html( $notice['message'] ) . '</p>';

		if ( ! empty( $notice['results'] ) && is_array( $notice['results'] ) ) {
			echo '<ul style="margin:0;">';

			foreach ( $notice['results'] as $transport => $ok ) {
				printf(
					'<li><strong>%s</strong>: %s</li>',
					esc_html( $transport ),
					$ok ? esc_html__( 'delivered', 'wp-messenger-forward' ) : esc_html__( 'failed — see the error above', 'wp-messenger-forward' )
				);
			}

			echo '</ul>';
		}

		echo '</div>';
	}

	/**
	 * @param array $notice Notice payload.
	 */
	private static function remember_admin_notice( $notice ) {
		set_transient( 'wpmf_admin_notice', $notice, 2 * MINUTE_IN_SECONDS );
	}

	/**
	 * @return array|null
	 */
	private static function pull_admin_notice() {
		$notice = get_transient( 'wpmf_admin_notice' );

		if ( ! is_array( $notice ) ) {
			return null;
		}

		delete_transient( 'wpmf_admin_notice' );

		return $notice;
	}

	/**
	 * Persist the submitted settings, optionally sending a test message.
	 */
	public static function handle_settings_save() {
		if ( ! current_user_can( 'manage_options' ) ) {
			wp_die( esc_html__( 'You are not allowed to change these settings.', 'wp-messenger-forward' ), '', array( 'response' => 403 ) );
		}

		check_admin_referer( 'wpmf_save_settings', 'wpmf_settings_nonce' );

		$stored = get_option( self::OPTION_NAME, array() );
		$raw    = is_array( $stored ) ? $stored : array();

		foreach ( array_keys( self::defaults() ) as $key ) {
			if ( 'events' === $key ) {
				continue;
			}

			if ( isset( $_POST[ $key ] ) ) {
				$raw[ $key ] = wp_unslash( $_POST[ $key ] ); // phpcs:ignore WordPress.Security.ValidatedSanitizedInput -- sanitised by normalize_options().
			} elseif ( in_array( $key, self::checkbox_keys(), true ) ) {
				// Unchecked boxes are absent from the POST body: that is a real "no".
				$raw[ $key ] = false;
			}
		}

		$events = array();

		foreach ( array_keys( self::event_definitions() ) as $event ) {
			$events[ $event ] = isset( $_POST['events'][ $event ] );
		}

		$raw['events'] = $events;

		// The HTTP ingest endpoint is useless without a secret, so hand the
		// operator one as soon as they switch the relay on.
		if ( ! empty( $raw['relay_enabled'] ) && empty( $raw['ingest_secret'] ) ) {
			$raw['ingest_secret'] = bin2hex( random_bytes( 16 ) );
		}

		update_option( self::OPTION_NAME, self::normalize_options( $raw ) );
		self::$settings_cache = null;

		self::schedule_relay();

		$results = array();
		$message = __( 'Settings saved.', 'wp-messenger-forward' );
		$level   = 'success';

		if ( isset( $_POST['wpmf_test'] ) ) {
			$results = self::send_test_message();

			if ( empty( $results ) ) {
				$level   = 'warning';
				$message = __( 'Settings saved, but no messenger is configured, so the test message had nowhere to go.', 'wp-messenger-forward' );
			} elseif ( ! in_array( true, $results, true ) ) {
				$level   = 'error';
				$message = __( 'Settings saved, but every transport rejected the test message.', 'wp-messenger-forward' );
			}
		}

		self::remember_admin_notice(
			array(
				'message' => $message,
				'level'   => $level,
				'results' => $results,
			)
		);

		wp_safe_redirect(
			add_query_arg(
				array(
					'page'               => 'wp-messenger-forward',
					'wpmf_notice'        => 1,
				),
				admin_url( 'options-general.php' )
			)
		);
		exit;
	}

	/**
	 * Add a Settings link on the plugins screen.
	 *
	 * @param array $links Existing links.
	 * @return array
	 */
	public static function plugin_action_links( $links ) {
		array_unshift(
			$links,
			'<a href="' . esc_url( admin_url( 'options-general.php?page=wp-messenger-forward' ) ) . '">' . esc_html__( 'Settings', 'wp-messenger-forward' ) . '</a>'
		);

		return $links;
	}

	/* ---------------------------------------------------------------------
	 * Admin: support inbox
	 * ------------------------------------------------------------------ */

	/**
	 * Conversation row by id.
	 *
	 * @param int $conversation_id Conversation id.
	 * @return array|null
	 */
	private static function conversation_by_id( $conversation_id ) {
		global $wpdb;

		$table = self::table( 'conversations' );

		return $wpdb->get_row(
			$wpdb->prepare( "SELECT * FROM $table WHERE id = %d LIMIT 1", (int) $conversation_id ),
			ARRAY_A
		);
	}

	/**
	 * Message bodies for a set of message ids, keyed by id (single query).
	 *
	 * @param array $message_ids Message ids.
	 * @return array<int,string>
	 */
	private static function last_messages_for( array $message_ids ) {
		global $wpdb;

		$message_ids = array_values( array_filter( array_map( 'absint', $message_ids ) ) );

		if ( empty( $message_ids ) ) {
			return array();
		}

		$messages     = self::table( 'messages' );
		$placeholders = implode( ',', array_fill( 0, count( $message_ids ), '%d' ) );
		$rows         = $wpdb->get_results(
			$wpdb->prepare( "SELECT id, message FROM $messages WHERE id IN ($placeholders)", $message_ids ),
			ARRAY_A
		);

		$found = array();

		foreach ( (array) $rows as $row ) {
			$found[ (int) $row['id'] ] = (string) $row['message'];
		}

		return $found;
	}

	/**
	 * List conversations and render a single thread.
	 */
	public static function chat_admin_page() {
		if ( ! current_user_can( 'edit_posts' ) ) {
			wp_die( esc_html__( 'You are not allowed to read the support inbox.', 'wp-messenger-forward' ) );
		}

		echo '<div class="wrap">';
		echo '<h1>' . esc_html__( 'Support Chat', 'wp-messenger-forward' ) . '</h1>';

		self::render_admin_notice( self::pull_admin_notice() );

		if ( ! self::chat_tables_exist() ) {
			printf(
				'<div class="notice notice-error"><p>%s</p></div>',
				esc_html__( 'The chat tables do not exist. Deactivate and reactivate the plugin to create them.', 'wp-messenger-forward' )
			);
			echo '</div>';

			return;
		}

		$conversation_id = isset( $_GET['conversation'] ) ? absint( wp_unslash( $_GET['conversation'] ) ) : 0;

		if ( $conversation_id > 0 ) {
			self::render_chat_thread( $conversation_id );
			echo '</div>';

			return;
		}

		self::render_chat_list();
		echo '</div>';
	}

	/**
	 * The inbox list with status filters and a search box.
	 */
	private static function render_chat_list() {
		$per_page = 25;
		$paged    = isset( $_GET['paged'] ) ? max( 1, absint( wp_unslash( $_GET['paged'] ) ) ) : 1;
		$status   = isset( $_GET['status'] ) ? sanitize_key( wp_unslash( $_GET['status'] ) ) : '';
		$search   = isset( $_GET['s'] ) ? sanitize_text_field( wp_unslash( $_GET['s'] ) ) : '';

		$total = self::count_conversations( $status, $search );

		echo '<form method="get" style="margin-bottom:12px;">';
		echo '<input type="hidden" name="page" value="wp-messenger-forward-chat">';
		echo '<select name="status" onchange="this.form.submit()">';

		foreach ( array(
			''         => __( 'All conversations', 'wp-messenger-forward' ),
			'open'     => __( 'Open', 'wp-messenger-forward' ),
			'pending'  => __( 'Pending', 'wp-messenger-forward' ),
			'closed'   => __( 'Closed', 'wp-messenger-forward' ),
		) as $option => $label ) {
			printf(
				'<option value="%s"%s>%s</option>',
				esc_attr( $option ),
				selected( $status, $option, false ),
				esc_html( $label )
			);
		}

		echo '</select> ';
		echo '<input type="search" name="s" value="' . esc_attr( $search ) . '" placeholder="' . esc_attr__( 'Ticket, name or email', 'wp-messenger-forward' ) . '"> ';
		echo '<button type="submit" class="button">' . esc_html__( 'Filter', 'wp-messenger-forward' ) . '</button>';
		echo '</form>';

		$rows = self::list_conversations( $status, $per_page, ( $paged - 1 ) * $per_page, $search );

		if ( empty( $rows ) ) {
			echo '<p>' . esc_html__( 'No conversations yet. Add the [customer_chat] shortcode to a page to start one.', 'wp-messenger-forward' ) . '</p>';

			return;
		}

		echo '<table class="widefat striped"><thead><tr>';

		foreach ( array( 'Ticket', 'Customer', 'Last message', 'Unread', 'Status', 'Updated' ) as $column ) {
			echo '<th>' . esc_html( $column ) . '</th>';
		}

		echo '</tr></thead><tbody>';

		$last_texts = self::last_messages_for( wp_list_pluck( $rows, 'id' ) );

		foreach ( $rows as $row ) {
			$last = isset( $last_texts[ (int) $row['last_message_id'] ] ) ? $last_texts[ (int) $row['last_message_id'] ] : null;
			$unread        = (int) $row['unread_agents'];
			$customer      = trim( (string) $row['customer_name'] );
			$customer      = '' !== $customer ? $customer . ' · ' . (string) $row['customer_email'] : (string) $row['customer_email'];
			$thread_url    = admin_url( 'admin.php?page=wp-messenger-forward-chat&conversation=' . (int) $row['id'] );

			echo '<tr>';
			echo '<td><a href="' . esc_url( $thread_url ) . '"><strong>#' . esc_html( self::ticket_tag( (string) $row['ticket'] ) ) . '</strong></a></td>';
			echo '<td>' . esc_html( $customer ) . '</td>';
			echo '<td>' . esc_html( $last ? self::truncate( (string) $last, 90 ) : '' ) . '</td>';
			echo '<td>' . ( $unread > 0 ? '<span style="color:#d63638;font-weight:600;">' . (int) $unread . '</span>' : '0' ) . '</td>';
			echo '<td>' . esc_html( (string) $row['status'] ) . '</td>';
			echo '<td>' . esc_html( self::format_datetime( (string) $row['updated_at'] ) ) . '</td>';
			echo '</tr>';
		}

		echo '</tbody></table>';

		$pages = (int) ceil( $total / $per_page );

		if ( $pages > 1 ) {
			echo '<p>';

			for ( $page = 1; $page <= $pages; $page++ ) {
				$url = add_query_arg(
					array(
						'page'   => 'wp-messenger-forward-chat',
						'paged'  => $page,
						'status' => $status,
						's'      => $search,
					),
					admin_url( 'admin.php' )
				);

				printf(
					'%s <a href="%s">%d</a>',
					$page > 1 ? '·' : '',
					esc_url( $url ),
					(int) $page
				);
			}

			echo '</p>';
		}
	}

	/**
	 * A single thread with the reply form.
	 *
	 * @param int $conversation_id Conversation id.
	 */
	private static function render_chat_thread( $conversation_id ) {
		$conversation = self::conversation_by_id( $conversation_id );

		if ( ! $conversation ) {
			echo '<p>' . esc_html__( 'This conversation no longer exists.', 'wp-messenger-forward' ) . '</p>';

			return;
		}

		$thread_url = admin_url( 'admin.php?page=wp-messenger-forward-chat&conversation=' . (int) $conversation['id'] );

		echo '<p><a href="' . esc_url( admin_url( 'admin.php?page=wp-messenger-forward-chat' ) ) . '">← ' . esc_html__( 'All conversations', 'wp-messenger-forward' ) . '</a></p>';
		echo '<table class="widefat striped" style="max-width:820px;"><tbody>';
		echo '<tr><th style="width:140px;">' . esc_html__( 'Ticket', 'wp-messenger-forward' ) . '</th><td>' . esc_html( self::ticket_tag( (string) $conversation['ticket'] ) ) . '</td></tr>';
		echo '<tr><th>' . esc_html__( 'Customer', 'wp-messenger-forward' ) . '</th><td>' . esc_html( trim( (string) $conversation['customer_name'] . ' ' . (string) $conversation['customer_email'] ) ) . '</td></tr>';
		echo '<tr><th>' . esc_html__( 'Status', 'wp-messenger-forward' ) . '</th><td>' . esc_html( (string) $conversation['status'] ) . '</td></tr>';
		echo '<tr><th>' . esc_html__( 'Started', 'wp-messenger-forward' ) . '</th><td>' . esc_html( self::format_datetime( (string) $conversation['created_at'] ) ) . '</td></tr>';
		echo '<tr><th>' . esc_html__( 'Messenger reply', 'wp-messenger-forward' ) . '</th><td><code>' . esc_html( self::ticket_tag( (string) $conversation['ticket'] ) ) . ' ' . esc_html__( 'in your chat, or reply to the forwarded message', 'wp-messenger-forward' ) . '</code></td></tr>';
		echo '</tbody></table>';

		echo '<div id="wpmf-thread" style="max-width:820px;border:1px solid #dcdcde;border-radius:8px;padding:14px;margin:16px 0;background:#fff;">';

		foreach ( self::latest_messages( (int) $conversation['id'], 300 ) as $message ) {
			$is_agent = 'agent' === $message['sender'];

			printf(
				'<p style="margin:0 0 12px;%1$s"><strong>%2$s</strong><br>%3$s<em style="color:#787c82;font-size:11px;"> %4$s</em></p>',
				$is_agent ? 'background:#f6f7f7;padding:8px;border-left:3px solid #2271b1;' : '',
				esc_html( '' !== (string) $message['author_name'] ? (string) $message['author_name'] : ( $is_agent ? __( 'Support', 'wp-messenger-forward' ) : __( 'Customer', 'wp-messenger-forward' ) ) ),
				esc_html( (string) $message['message'] ),
				esc_html( self::format_datetime( (string) $message['created_at'] ) )
			);
		}

		echo '</div>';

		echo '<form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '" style="max-width:820px;">';
		wp_nonce_field( 'wpmf_chat_action', 'wpmf_chat_nonce' );
		echo '<input type="hidden" name="action" value="wpmf_chat_action">';
		echo '<input type="hidden" name="conversation_id" value="' . (int) $conversation['id'] . '">';
		echo '<textarea name="reply" rows="4" class="large-text" placeholder="' . esc_attr__( 'Your reply to the customer…', 'wp-messenger-forward' ) . '"></textarea>';
		echo '<p>';
		echo '<button type="submit" name="chat_action" value="reply" class="button button-primary">' . esc_html__( 'Send reply', 'wp-messenger-forward' ) . '</button> ';
		echo '<button type="submit" name="chat_action" value="close" class="button">' . esc_html__( 'Close conversation', 'wp-messenger-forward' ) . '</button> ';
		echo '<button type="submit" name="chat_action" value="reopen" class="button">' . esc_html__( 'Reopen', 'wp-messenger-forward' ) . '</button> ';
		echo '<a href="' . esc_url( $thread_url ) . '" class="button button-link">' . esc_html__( 'Refresh', 'wp-messenger-forward' ) . '</a>';
		echo '</p>';
		echo '</form>';
	}

	/**
	 * Handle reply/close/reopen from the inbox.
	 */
	public static function handle_chat_admin_action() {
		if ( ! current_user_can( 'edit_posts' ) ) {
			wp_die( esc_html__( 'You are not allowed to answer conversations.', 'wp-messenger-forward' ), '', array( 'response' => 403 ) );
		}

		check_admin_referer( 'wpmf_chat_action', 'wpmf_chat_nonce' );

		$conversation_id = isset( $_POST['conversation_id'] ) ? absint( wp_unslash( $_POST['conversation_id'] ) ) : 0;
		$conversation    = $conversation_id ? self::conversation_by_id( $conversation_id ) : null;

		if ( ! $conversation ) {
			wp_die( esc_html__( 'Unknown conversation.', 'wp-messenger-forward' ) );
		}

		$action  = isset( $_POST['chat_action'] ) ? sanitize_key( wp_unslash( $_POST['chat_action'] ) ) : '';
		$admin   = wp_get_current_user();
		$author  = '' !== (string) $admin->display_name ? (string) $admin->display_name : (string) $admin->user_login;
		$notice  = '';
		$level   = 'success';

		if ( 'reply' === $action ) {
			$reply = isset( $_POST['reply'] ) ? self::truncate( self::to_plain_text( wp_unslash( $_POST['reply'] ) ), 2000 ) : '';

			if ( '' === $reply ) {
				self::remember_admin_notice(
					array(
						'message' => __( 'Write a reply before sending it.', 'wp-messenger-forward' ),
						'level'   => 'error',
					)
				);
			} else {
				self::add_agent_message( $conversation_id, $author, $reply );

				// Copy the answer into the messenger channel too, so the team
				// keeps one shared history. Guarded by the same ticket tag.
				if ( self::event_enabled( 'forward_chat_message' ) && self::has_transport() ) {
					self::send_to_messengers(
						self::build_message(
							'💬 ' . __( 'Support reply', 'wp-messenger-forward' ) . ' ' . self::ticket_tag( (string) $conversation['ticket'] ),
							array( 'Ticket' => self::ticket_tag( (string) $conversation['ticket'] ) ),
							array( $reply )
						)
					);
				}

				$notice = __( 'Reply sent to the customer.', 'wp-messenger-forward' );
			}
		} elseif ( 'close' === $action ) {
			self::set_conversation_status( $conversation_id, 'closed' );
			self::insert_message( $conversation_id, 'agent', $author, __( 'This conversation has been closed.', 'wp-messenger-forward' ) );
			$notice = __( 'Conversation closed.', 'wp-messenger-forward' );
		} elseif ( 'reopen' === $action ) {
			self::set_conversation_status( $conversation_id, 'open' );
			$notice = __( 'Conversation reopened.', 'wp-messenger-forward' );
		} else {
			$level  = 'error';
			$notice = __( 'Unknown action.', 'wp-messenger-forward' );
		}

		if ( '' !== $notice ) {
			self::remember_admin_notice(
				array(
					'message' => $notice,
					'level'   => $level,
				)
			);
		}

		wp_safe_redirect(
			add_query_arg(
				array(
					'page'         => 'wp-messenger-forward-chat',
					'conversation' => (int) $conversation_id,
					'wpmf_notice'  => 1,
				),
				admin_url( 'admin.php' )
			)
		);
		exit;
	}
}

/*
 * Keep the public bootstrap of 2.0 intact so the file still works when it is
 * dropped into a WordPress install without an autoloader.
 */
WP_Messenger_Forward::ensure_defaults();
WP_Messenger_Forward::init();
